package com.classictreerun;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Pure observation/estimate model. Times are conservative estimates, not remote crop checks. */
final class CropGrowth
{
    private static final DateTimeFormatter READY_TIME = DateTimeFormatter.ofPattern("EEE HH:mm");
    static final class Observation
    {
        final int raw; final long observedAt, readyAt, cycle; final boolean armed, seasonal;
        Observation(int raw,long observedAt,long readyAt,long cycle,boolean armed,boolean seasonal)
        { this.raw=raw;this.observedAt=observedAt;this.readyAt=readyAt;this.cycle=cycle;this.armed=armed;this.seasonal=seasonal; }
        String encode() { return raw+","+observedAt+","+readyAt+","+cycle+","+armed+","+seasonal; }
    }
    static final class Group
    {
        final int total, unknown, blocked, ready; final long readyAt; final boolean armed; final String fingerprint;
        Group(int total,int unknown,int blocked,int ready,long readyAt,boolean armed,String fingerprint)
        { this.total=total;this.unknown=unknown;this.blocked=blocked;this.ready=ready;this.readyAt=readyAt;this.armed=armed;this.fingerprint=fingerprint; }
        boolean ready(long now) { return total>0 && unknown==0 && blocked==0 && readyAt<=now; }
    }
    final Map<Patch,Observation> observations=new EnumMap<>(Patch.class);
    final CropReference reference;
    CropGrowth(CropReference reference) { this.reference=reference; }

    boolean observe(Patch patch,int raw,long now,boolean seasonal)
    {
        Observation old=observations.get(patch); CropReference.Crop crop=reference.decode(patch,raw);
        if (old!=null && old.raw==raw && old.seasonal==seasonal && now-old.observedAt<300
            && (old.readyAt==0 || old.readyAt>now || crop!=null && crop.ready())) { return false; }
        CropReference.Crop previous=old==null?null:reference.decode(patch,old.raw);
        boolean sameCycle=old!=null && previous!=null && crop!=null && previous.produce.equals(crop.produce);
        boolean regrowing=sameCycle && "HARVESTABLE".equals(crop.state) && "HARVESTABLE".equals(previous.state) && crop.stage<previous.stage && crop.tickMinutes>0;
        boolean plantedAgain=sameCycle && "GROWING".equals(crop.state) && (crop.stage<previous.stage || "HARVESTABLE".equals(previous.state) && crop.stage==0);
        long cycle=old!=null && sameCycle && !regrowing && !plantedAgain ? old.cycle : now;
        boolean stump=reference.isStump(patch,raw);
        boolean growing=crop!=null && crop.healthy() && !crop.ready() && !stump;
        boolean armed=growing || sameCycle && old!=null && old.armed && !plantedAgain;
        long readyAt=0;
        if (crop!=null && crop.healthy() && !stump)
        {
            if (crop.ready()) { readyAt=now; }
            else if (crop.tickMinutes>0)
            {
                long seconds=(long)crop.tickMinutes*60*(seasonal?1:5)/5;
                readyAt=now+crop.remaining()*seconds;
                if (sameCycle && !regrowing && !plantedAgain && old.readyAt>now) { readyAt=Math.min(readyAt,old.readyAt); }
            }
        }
        observations.put(patch,new Observation(raw,now,readyAt,cycle,armed,seasonal)); return true;
    }
    boolean isKnownReady(Patch patch,long now)
    {
        Observation value=observations.get(patch); if(value==null)return false;
        CropReference.Crop crop=reference.decode(patch,value.raw);
        return crop!=null && crop.healthy() && !reference.isStump(patch,value.raw) && value.readyAt>0 && value.readyAt<=now;
    }
    Group group(Collection<Patch> patches,long now)
    {
        int unknown=0,blocked=0,ready=0;long end=0;boolean armed=false;StringBuilder fingerprint=new StringBuilder();
        Set<Patch> selected=EnumSet.noneOf(Patch.class);selected.addAll(patches);
        for(Patch patch:selected)
        {
            Observation value=observations.get(patch);
            if(value==null){unknown++;continue;}
            CropReference.Crop crop=reference.decode(patch,value.raw);
            if(crop==null){unknown++;continue;}
            if(!crop.healthy() || reference.isStump(patch,value.raw) || value.readyAt<=0){blocked++;continue;}
            if(value.readyAt<=now){ready++;}
            end=Math.max(end,value.readyAt);armed|=value.armed;
            fingerprint.append(patch.name()).append(':').append(value.cycle).append(';');
        }
        return new Group(selected.size(),unknown,blocked,ready,end,armed,fingerprint.toString());
    }
    String summary(Collection<Patch> patches,long now)
    {
        Group group=group(patches,now);
        if(group.total==0)return "Next run: no patches selected.";
        if(group.unknown>0 || group.blocked>0)return "Next full run: "+group.ready+"/"+group.total+" ready; "+group.unknown+" unknown, "+group.blocked+" need planting or care.";
        return group.ready(now)?"All "+group.total+" patches estimated ready for the next full run.":"Next full run estimated in "+duration(group.readyAt-now)+" ("+at(group.readyAt)+").";
    }
    String describe(Patch patch,long now)
    {
        Observation value=observations.get(patch);if(value==null)return "Growth unknown - visit this patch to track it.";
        CropReference.Crop crop=reference.decode(patch,value.raw);if(crop==null)return "Unknown crop state - no reliable timer.";
        if(!crop.planted())return "Empty / no crop observed. No growth timer.";
        if(reference.isStump(patch,value.raw))return crop.label()+": stump when last observed - clear and replant. No growth timer.";
        if(!crop.healthy())return crop.label()+": "+crop.state.toLowerCase(Locale.ROOT)+" - needs attention.";
        if(value.readyAt<=0)return crop.label()+": no reliable ready estimate.";
        if(crop.anima())
        {
            if(value.readyAt<=now)return crop.label()+": "+(crop.ready()?"expired when last observed; replace":"estimated expired; revisit to replace")+".";
            return crop.label()+": "+(crop.stage==crop.stages-2?"withering; ":"active when observed; ")+"replacement est. in "+duration(value.readyAt-now)+" ("+at(value.readyAt)+").";
        }
        if(value.readyAt<=now)return crop.label()+": "+(crop.ready()?"ready when last observed":"estimated ready; revisit to confirm health")+".";
        String prefix="HARVESTABLE".equals(crop.state)?"full regrowth est.":"est. ready";
        return crop.label()+": "+prefix+" in "+duration(value.readyAt-now)+" ("+at(value.readyAt)+").";
    }
    String save()
    {
        StringJoiner encoded=new StringJoiner(";"); observations.forEach((patch,value)->encoded.add(patch.name()+"="+value.encode())); return encoded.toString();
    }
    void load(String text)
    {
        observations.clear();if(text==null)return;
        for(String entry:text.split(";"))
        {
            try
            {
                String[] pair=entry.split("=",2),v=pair[1].split(",");if(v.length!=6)continue;
                long at=Long.parseLong(v[1]),ready=Long.parseLong(v[2]),cycle=Long.parseLong(v[3]);
                int raw=Integer.parseInt(v[0]);
                if(at<=0 || at>Instant.now().getEpochSecond()+86400 || ready<0 || ready>at+366L*86400 || cycle<=0 || cycle>at || raw<0 || raw>65535
                    || !("true".equals(v[4]) || "false".equals(v[4])) || !("true".equals(v[5]) || "false".equals(v[5])))continue;
                observations.put(Patch.valueOf(pair[0]),new Observation(raw,at,ready,cycle,Boolean.parseBoolean(v[4]),Boolean.parseBoolean(v[5])));
            }
            catch(IllegalArgumentException | ArrayIndexOutOfBoundsException ignored){/* Preserve other valid observations. */}
        }
    }
    static String duration(long seconds)
    {
        long minutes=Math.max(1,(seconds+59)/60);long days=minutes/1440,hours=minutes%1440/60,mins=minutes%60;
        return (days>0?days+"d ":"")+(hours>0?hours+"h ":"")+(mins>0?mins+"m":hours==0&&days==0?"1m":"");
    }
    static String at(long seconds){return READY_TIME.format(Instant.ofEpochSecond(seconds).atZone(ZoneId.systemDefault()));}
}

package com.classictreerun;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Versioned, attributed data tables. No runtime use of private RuneLite farming APIs. */
final class CropReference
{
    static final class Crop
    {
        final String produce, state;
        final int stage, stages, tickMinutes;
        Crop(String produce, String state, int stage, int stages, int tickMinutes)
        { this.produce=produce; this.state=state; this.stage=stage; this.stages=stages; this.tickMinutes=tickMinutes; }
        boolean planted() { return !"WEEDS".equals(produce) && !"SCARECROW".equals(produce); }
        boolean healthy() { return planted() && !"DEAD".equals(state) && !"DISEASED".equals(state); }
        int remaining() { return Math.max(0, stages - 1 - stage); }
        boolean ready() { return healthy() && ("HARVESTABLE".equals(state) ? tickMinutes == 0 || remaining() == 0 : remaining() == 0); }
        boolean anima() { return "ATTAS".equals(produce) || "IASOR".equals(produce) || "KRONOS".equals(produce); }
        String label() { return produce.toLowerCase(java.util.Locale.ROOT).replace('_',' '); }
    }
    static final class Range
    {
        final int from, to; final Crop crop;
        Range(int from,int to,Crop crop) { this.from=from;this.to=to;this.crop=crop; }
    }
    static final class Binding
    {
        final Patch patch; final int sourceRegion, varbit; final String implementation; final Set<Integer> regions;
        Binding(Patch patch,int sourceRegion,int varbit,String implementation,Set<Integer> regions)
        { this.patch=patch;this.sourceRegion=sourceRegion;this.varbit=varbit;this.implementation=implementation;this.regions=regions; }
        boolean applies(int x,int y,int plane)
        {
            int region = ((x >> 6) << 8) | (y >> 6);
            if (!regions.contains(region)) { return false; }
            // Distinct payloads share these regions. Boundary rules are attributed in THIRD-PARTY-NOTICES.md.
            if (sourceRegion == 11062 && x >= 2816 && y < 3456) { return x < 2840 && y >= 3440 && plane == 0; }
            if (sourceRegion == 11317) { return x >= 2840 || y < 3440 || plane == 1; }
            if (sourceRegion == 12083) { return y >= 3272; }
            if (sourceRegion == 12082) { return y < 3272; }
            if (sourceRegion == 14651)
            {
                if (plane != 0 || x == 3753 && y >= 3868 && y <= 3870) { return false; }
                if ((x == 3729 || x == 3728 || x == 3747 || x == 3746) && y >= 3830 && y <= 3832) { return false; }
            }
            return true;
        }
    }
    private final Map<String,List<Range>> states = new HashMap<>();
    private final Map<String,Set<Integer>> stumps = new HashMap<>();
    private final Map<Integer,List<Binding>> regions = new HashMap<>();
    final Map<Patch,Binding> bindings = new EnumMap<>(Patch.class);
    CropReference()
    {
        for (String[] row : rows("crop-states.csv"))
        {
            Crop crop = new Crop(row[3],row[4],Integer.parseInt(row[5]),Integer.parseInt(row[6]),Integer.parseInt(row[7]));
            states.computeIfAbsent(row[0], key -> new ArrayList<>()).add(new Range(Integer.parseInt(row[1]),Integer.parseInt(row[2]),crop));
        }
        for (String[] row : rows("patch-bindings.csv"))
        {
            Set<Integer> regions = new HashSet<>(); for (String id : row[4].split(";")) { regions.add(Integer.parseInt(id)); }
            Patch patch=Patch.valueOf(row[0]);
            Binding binding = new Binding(patch,Integer.parseInt(row[1]),Integer.parseInt(row[2]),row[3],regions);
            bindings.put(patch,binding);
            for (int region : regions) { this.regions.computeIfAbsent(region, key -> new ArrayList<>()).add(binding); }
        }
        for (String[] row : rows("crop-stumps.csv"))
        { stumps.computeIfAbsent(row[0], key -> new HashSet<>()).add(Integer.parseInt(row[1])); }
        if (bindings.size() != Patch.values().length) { throw new IllegalStateException("Incomplete crop reference"); }
    }
    Crop decode(Patch patch,int raw)
    {
        Binding binding=bindings.get(patch);
        if (raw < 0 || raw > 65535) { return null; }
        List<Range> ranges = states.get(binding.implementation);
        int low=0, high=ranges.size()-1;
        while (low<=high)
        {
            int middle=(low+high)>>>1; Range range=ranges.get(middle);
            if (raw<range.from) { high=middle-1; }
            else if (raw>range.to) { low=middle+1; }
            else { return range.crop; }
        }
        return null;
    }
    boolean isStump(Patch patch,int raw)
    { return stumps.getOrDefault(bindings.get(patch).implementation,Collections.emptySet()).contains(raw); }
    List<Binding> nearby(int x,int y)
    { return regions.getOrDefault(((x>>6)<<8)|(y>>6),Collections.emptyList()); }
    private static List<String[]> rows(String resource)
    {
        List<String[]> result=new ArrayList<>();
        try (InputStream stream=CropReference.class.getResourceAsStream(resource))
        {
            if (stream==null) { throw new IllegalStateException("Missing farming reference: "+resource); }
            try (BufferedReader reader=new BufferedReader(new InputStreamReader(stream,StandardCharsets.UTF_8)))
            {
                String line; while ((line=reader.readLine())!=null) { if (!line.isEmpty() && !line.startsWith("#")) { result.add(line.split(",",-1)); } }
            }
        }
        catch (IOException error) { throw new IllegalStateException("Couldn't read farming reference",error); }
        return result;
    }
}

package com.classictreerun;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/** Stable local fingerprints without per-byte formatter allocation. */
final class Digests
{
    private Digests() { }
    static String sha256(String value)
    {
        try
        {
            byte[] hash=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            char[] hex="0123456789abcdef".toCharArray(),text=new char[hash.length*2];
            for(int i=0;i<hash.length;i++){int part=hash[i]&255;text[i*2]=hex[part>>>4];text[i*2+1]=hex[part&15];}
            return new String(text);
        }
        catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}
    }
}

package com.classictreerun;

import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;

/** Stable native enum choices; labels reflect this profile's locally saved slot names. */
public enum EditorPreset
{
    CURRENT,
    SLOT_01, SLOT_02, SLOT_03, SLOT_04, SLOT_05, SLOT_06, SLOT_07, SLOT_08, SLOT_09, SLOT_10, SLOT_11, SLOT_12, SLOT_13, SLOT_14, SLOT_15, SLOT_16, SLOT_17, SLOT_18, SLOT_19, SLOT_20, SLOT_21, SLOT_22, SLOT_23, SLOT_24, SLOT_25, SLOT_26, SLOT_27, SLOT_28, SLOT_29, SLOT_30, SLOT_31, SLOT_32;

    private static volatile Map<EditorPreset, String> labels = Collections.emptyMap();
    static void publish(Map<EditorPreset, String> names)
    {
        Map<EditorPreset, String> copy = new EnumMap<>(EditorPreset.class);
        copy.putAll(names); labels = Collections.unmodifiableMap(copy);
    }
    static void clearLabels() { labels = Collections.emptyMap(); }
    @Override public String toString()
    {
        if (this == CURRENT) { return "New / current run"; }
        String name = labels.get(this);
        if (name == null) { return number() + ": Empty"; }
        int count = name.codePointCount(0, name.length());
        String shortName = count > 14 ? name.substring(0, name.offsetByCodePoints(0, 14)) + "..." : name;
        return number() + ": " + shortName;
    }
    int number() { return this == CURRENT ? 0 : Integer.parseInt(name().substring(5)); }
}

package com.classictreerun;

import java.util.*;
import java.util.function.*;
import javax.swing.Timer;

/** EDT-owned readiness records and one notification per saved preset/crop cycle. */
final class GrowthMonitor
{
    private final ClassicTreeRunConfig config;
    private final ClassicTreeRunPanel.Preferences preferences;
    private final ClassicTreeRunPanel panel;
    private final Consumer<String> notify;
    private final LongSupplier clock;
    private final CropReference reference;
    private final Timer timer;
    private CropGrowth growth;
    private String characterKey;
    private boolean allowNotifications, disposed, dirty;
    private String pendingProgress;
    private final Map<String,String> pendingWrites=new LinkedHashMap<>();
    private String presetSnapshot;
    private final Map<String,List<Patch>> presetPatches=new LinkedHashMap<>();

    GrowthMonitor(ClassicTreeRunConfig config,ClassicTreeRunPanel.Preferences preferences,ClassicTreeRunPanel panel,
        Consumer<String> notify,CropReference reference,LongSupplier clock,boolean startTimer)
    {
        this.config=config;this.preferences=preferences;this.panel=panel;this.notify=notify;this.reference=reference;this.clock=clock;
        panel.setProgressEdited(this::discardPendingCompletion);
        timer=new Timer(10000,event->poll());if(startTimer)timer.start();
    }
    private void discardPendingCompletion()
    {
        // A successful manual change supersedes failed automatic progress, but keeps crop observations.
        pendingProgress=null;pendingWrites.remove(ClassicTreeRunPanel.PROGRESS_KEY);
    }
    void allowNotifications(boolean allow){allowNotifications=allow;}
    void accept(String character,List<GrowthSampler.Sample> samples,boolean seasonal)
    {
        if(disposed || !config.trackGrowth())return;
        if(!character.equals(characterKey))
        {
            flush(); // Queue failed writes under the old character before changing context.
            characterKey=character;growth=new CropGrowth(reference);
            growth.load(pendingWrites.containsKey(dataKey())?pendingWrites.get(dataKey()):preferences.get(dataKey()));panel.setGrowth(growth);
        }
        allowNotifications=true;long now=clock.getAsLong();boolean changed=false,completionChanged=false;
        RouteState progress=null;
        Set<Patch> active=config.autoCompleteReplanted() && !samples.isEmpty()?new HashSet<>(RouteState.active(config)):Collections.emptySet();
        for(GrowthSampler.Sample sample:samples)
        {
            CropGrowth.Observation old=growth.observations.get(sample.patch);
            CropReference.Crop before=old==null?null:reference.decode(sample.patch,old.raw),after=reference.decode(sample.patch,sample.raw);
            if(config.autoCompleteReplanted() && sample.transition && active.contains(sample.patch) && before!=null && after!=null
                && after.healthy() && "GROWING".equals(after.state) && after.stage==0
                && (!before.planted() || !before.healthy() || before.ready() || reference.isStump(sample.patch,old.raw) || !before.produce.equals(after.produce)))
            {
                if(progress==null)
                {
                    progress=new RouteState();
                    progress.load(pendingWrites.containsKey(ClassicTreeRunPanel.PROGRESS_KEY)?pendingWrites.get(ClassicTreeRunPanel.PROGRESS_KEY):preferences.get(ClassicTreeRunPanel.PROGRESS_KEY));
                }
                if(!progress.isDone(sample.patch)){progress.setDone(sample.patch,true);completionChanged=true;}
            }
            changed|=growth.observe(sample.patch,sample.raw,now,seasonal);
        }
        dirty|=changed;
        if(completionChanged)pendingProgress=progress.save();
        flush();
        if(completionChanged)panel.reload();else if(changed)panel.refreshGrowth(now);
    }
    private boolean flush()
    {
        if(dirty){pendingWrites.put(dataKey(),growth.save());dirty=false;}
        if(pendingProgress!=null){pendingWrites.put(ClassicTreeRunPanel.PROGRESS_KEY,pendingProgress);pendingProgress=null;}
        if(pendingWrites.isEmpty())return true;
        try{preferences.update(pendingWrites);pendingWrites.clear();return true;}
        catch(IllegalStateException error){panel.setStatus(error.getMessage());return false;}
    }
    void poll()
    {
        if(disposed || !config.trackGrowth() || growth==null)return;
        boolean saved=flush();long now=clock.getAsLong();panel.refreshGrowth(now);
        if(!saved || !allowNotifications || !config.notifyWhenReady())return;
        try
        {
            String snapshot=preferences.get(PresetLibrary.KEY);
            if(!Objects.equals(snapshot,presetSnapshot))
            {
                PresetLibrary library=new PresetLibrary(preferences);presetPatches.clear();
                for(String name:library.names())presetPatches.put(name,library.patches(name));
                presetSnapshot=snapshot;
            }
            for(Map.Entry<String,List<Patch>> preset:presetPatches.entrySet())
            {
                String name=preset.getKey();CropGrowth.Group group=growth.group(preset.getValue(),now);
                if(!group.ready(now) || !group.armed)continue;
                String marker="growthNoticeV1."+characterKey+"."+digest(name),fingerprint=digest(group.fingerprint);
                if(fingerprint.equals(preferences.get(marker)))continue;
                // Persist first: restarting or an OS notification failure must not cause repeated alerts.
                preferences.set(marker,fingerprint);
                notify.accept("Farm Run Planner: "+name+" - all "+group.total+" patches are estimated ready for your next full run. Check crop health when you visit.");
            }
        }
        catch(IllegalStateException error){panel.setStatus("Couldn't update local readiness reminders: "+error.getMessage());}
    }
    private String dataKey(){return "growthDataV1."+characterKey;}
    void dispose(){flush();disposed=true;timer.stop();}
    static String characterKey(long accountHash){return characterKey(accountHash,false,false);}
    static String characterKey(long accountHash,boolean seasonal,boolean deadman)
    {return digest(Long.toUnsignedString(accountHash)+":"+(deadman?"deadman":seasonal?"seasonal":"normal"));}
    static String digest(String value) { return Digests.sha256(value); }
}

package com.classictreerun;

import java.util.*;
import java.util.function.IntUnaryOperator;

/** Game-thread sampler: wait for region payloads to settle and require two matching reads. */
final class GrowthSampler
{
    static final class Sample
    {
        final Patch patch; final int raw; final boolean transition;
        Sample(Patch patch,int raw,boolean transition){this.patch=patch;this.raw=raw;this.transition=transition;}
    }
    private Set<Patch> area=EnumSet.noneOf(Patch.class);
    private final Map<Patch,Integer> previous=new EnumMap<>(Patch.class), committed=new EnumMap<>(Patch.class);
    private final Map<Patch,Integer> sent=new EnumMap<>(Patch.class);
    private int settle;
    private int reads;
    void reset(){area.clear();previous.clear();committed.clear();sent.clear();settle=0;reads=0;}
    List<Sample> read(CropReference reference,int x,int y,int plane,IntUnaryOperator varbits)
    {
        Set<Patch> current=EnumSet.noneOf(Patch.class);
        for(CropReference.Binding binding:reference.nearby(x,y))
        {if(binding.applies(x,y,plane))current.add(binding.patch);}
        if(!current.equals(area)){reset();area.addAll(current);}
        if(area.isEmpty() || settle++<3)return Collections.emptyList();
        reads++;
        List<Sample> samples=new ArrayList<>();
        for(Patch patch:area)
        {
            int raw=varbits.applyAsInt(reference.bindings.get(patch).varbit);
            Integer last=previous.put(patch,raw);
            if(last==null || last!=raw)continue;
            Integer old=committed.put(patch,raw);
            // Changed payloads immediately; unchanged observations at most once per ~5 minutes.
            if(old!=null && old==raw && reads-sent.get(patch)<500)continue;
            sent.put(patch,reads);
            samples.add(new Sample(patch,raw,old!=null && old!=raw));
        }
        return samples;
    }
}

package com.classictreerun;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;
import net.runelite.api.ItemComposition;

/** Immutable public item-definition flags. Contains no bank or character information. */
final class InventoryItemData
{
    static final InventoryItemData EMPTY=new InventoryItemData(Map.of());
    static final class ItemInfo
    {
        final boolean stackable, noteable;
        ItemInfo(boolean stackable,boolean noteable) { this.stackable=stackable;this.noteable=noteable; }
        @Override public String toString() { return (stackable?"s":"u")+(noteable?"n":"-"); }
    }
    private final Map<Integer,ItemInfo> items;
    InventoryItemData(Map<Integer,ItemInfo> items) { this.items=Map.copyOf(items); }
    boolean covers(Set<Integer> ids) { return items.keySet().containsAll(ids); }
    ItemInfo get(int item)
    {
        ItemInfo info=items.get(item);
        if(info==null)throw new IllegalArgumentException("Item data is not ready for "+item);
        return info;
    }
    InventoryItemData merge(InventoryItemData other)
    { Map<Integer,ItemInfo> joined=new LinkedHashMap<>(items);joined.putAll(other.items);return new InventoryItemData(joined); }
    String fingerprint(Set<Integer> ids)
    {
        Map<Integer,ItemInfo> used=new TreeMap<>();for(int id:ids)used.put(id,get(id));return used.toString();
    }
    static InventoryItemData read(Set<Integer> ids,java.util.function.IntFunction<ItemComposition> definitions)
    {
        Map<Integer,ItemInfo> values=new LinkedHashMap<>();
        for(int id:ids)
        {
            ItemComposition item=definitions.apply(id);
            values.put(id,new ItemInfo(item.isStackable(),item.getLinkedNoteId()!=-1));
        }
        return new InventoryItemData(values);
    }
}

package com.classictreerun;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Splits the prepared patch order into loads. No game actions or live pathfinding. */
final class InventoryLoadPlanner
{
    static final int BACKPACK_SLOTS=28;
    static final String BANKS_KEY="bankedInventoriesV1";
    static final class Load
    {
        final List<Patch> patches;
        final int slots;
        Load(List<Patch> patches,int slots) { this.patches=List.copyOf(patches);this.slots=slots; }
    }
    static final class Plan
    {
        final String signature;
        final List<Load> loads;
        final int capacity;
        Plan(String signature,List<Load> loads,int capacity)
        { this.signature=signature;this.loads=List.copyOf(loads);this.capacity=capacity; }
        int current(RouteState state)
        {
            for(int i=0;i<loads.size();i++)if(loads.get(i).patches.stream().anyMatch(p->!state.isDone(p)))return i;
            return -1;
        }
        boolean bankConfirmed(String record,int load)
        {
            if(load<=0)return true;
            if(record==null || !record.startsWith(signature+":"))return false;
            return RouteState.parse(record.substring(signature.length()+1)).contains(loads.get(load).patches.get(0));
        }
        String confirmBank(String record,int load)
        {
            java.util.Set<Patch> confirmed=new java.util.LinkedHashSet<>();
            if(record!=null && record.startsWith(signature+":"))confirmed.addAll(RouteState.parse(record.substring(signature.length()+1)));
            confirmed.add(loads.get(load).patches.get(0));return signature+":"+RouteState.encode(confirmed);
        }
        String reopenPatch(String record,Patch patch)
        {
            if(record==null || !record.startsWith(signature+":"))return "";
            java.util.Set<Patch> confirmed=new java.util.LinkedHashSet<>(RouteState.parse(record.substring(signature.length()+1)));
            boolean later=false;
            for(Load load:loads)
            {
                if(later)confirmed.remove(load.patches.get(0));
                if(load.patches.contains(patch))later=true;
            }
            return signature+":"+RouteState.encode(confirmed);
        }
        int startsAt(Patch patch)
        {
            for(int i=0;i<loads.size();i++)if(loads.get(i).patches.get(0)==patch)return i;
            return -1;
        }
    }

    static int reserved(ClassicTreeRunConfig config) { return Math.max(0,Math.min(27,config.loadReservedSlots())); }
    static String customInstructions(String text)
    {
        String clean=text==null?"":text.trim();
        if(clean.isEmpty())return "Travel to your chosen bank and resupply manually.";
        return clean.substring(0,Math.min(500,clean.length()));
    }
    static Map<String,String> settings(ClassicTreeRunConfig config)
    {
        Map<String,String> values=new LinkedHashMap<>();
        values.put("loadPlanning",Boolean.toString(config.loadPlanning()));
        values.put("loadReservedSlots",Integer.toString(reserved(config)));
        values.put("loadNotedProtection",Boolean.toString(config.loadNotedProtection()));
        values.put("loadBank",config.loadBank().name());
        values.put("loadBankInstructions",customInstructions(config.loadBankInstructions()));
        return values;
    }
    static void validate(String key,String value)
    {
        switch(key)
        {
            case "loadPlanning":case "loadNotedProtection":
                if(!("true".equals(value)||"false".equals(value)))throw new IllegalArgumentException("Invalid inventory option");return;
            case "loadReservedSlots":
                if(!value.matches("[0-9]{1,2}") || Integer.parseInt(value)>27)throw new IllegalArgumentException("Reserve between 0 and 27 slots");return;
            case "loadBank":BankDestination.valueOf(value);return;
            case "loadBankInstructions":if(value.length()>500)throw new IllegalArgumentException("Bank instructions must be at most 500 characters");return;
            default:throw new IllegalArgumentException("Unknown inventory option");
        }
    }

    static SupplyPlan supplies(ClassicTreeRunConfig config,List<Patch> patches,InventoryItemData data)
    { return SupplyPlan.build(config,patches).forInventory(config.loadNotedProtection(),data); }

    static int slots(SupplyPlan plan,InventoryItemData data)
    {
        Map<Integer,Long> loose=new HashMap<>(),noted=new HashMap<>();
        for(SupplyPlan.Requirement row:plan.requirements)
            (row.notedOnly?noted:loose).merge(row.item,(long)row.quantity,Long::sum);
        long slots=noted.size();
        for(Map.Entry<Integer,Long> row:loose.entrySet())slots+=data.get(row.getKey()).stackable?1:row.getValue();
        return (int)Math.min(Integer.MAX_VALUE,slots);
    }

    /** Adds each patch once per candidate load; shared tools/buckets are counted once per load. */
    static final class SlotCounter
    {
        private final InventoryItemData data;
        private final Map<Integer,Long> consumable=new HashMap<>(),reusable=new HashMap<>();
        private final java.util.Set<Integer> notes=new java.util.HashSet<>();
        private long occupied;
        SlotCounter(InventoryItemData data) { this.data=data; }
        int add(SupplyPlan patch)
        {
            for(SupplyPlan.Requirement row:patch.requirements)
            {
                if(row.notedOnly){if(notes.add(row.item))occupied++;continue;}
                long before=consumable.getOrDefault(row.item,0L)+reusable.getOrDefault(row.item,0L);
                if(row.reusable)reusable.merge(row.item,(long)row.quantity,Math::max);
                else consumable.merge(row.item,(long)row.quantity,Long::sum);
                long after=consumable.getOrDefault(row.item,0L)+reusable.getOrDefault(row.item,0L);
                occupied+=data.get(row.item).stackable?(before==0 && after>0?1:0):after-before;
            }
            return (int)Math.min(Integer.MAX_VALUE,occupied);
        }
    }

    static String signature(ClassicTreeRunConfig config,List<Patch> route,InventoryItemData data)
    {
        Map<String,String> travel=new java.util.TreeMap<>();
        travel.putAll(TravelCosts.settings(config));
        String source=RouteState.encode(route)+"\n"+CropChoices.settings(config)+"\n"+settings(config)+"\n"+travel+"\n"
            +data.fingerprint(SupplyPlan.build(config,route).items);
        return Digests.sha256(source);
    }

    static Plan plan(ClassicTreeRunConfig config,List<Patch> route,InventoryItemData data)
    {
        String signature=signature(config,route,data);
        int n=route.size(),capacity=BACKPACK_SLOTS-reserved(config);
        int[] count=new int[n+1],cost=new int[n+1],next=new int[n],occupied=new int[n];
        java.util.Arrays.fill(count,Integer.MAX_VALUE);java.util.Arrays.fill(cost,Integer.MAX_VALUE);count[n]=0;cost[n]=0;
        BankDestination bank=config.loadBank();
        List<SupplyPlan> perPatch=new ArrayList<>();
        for(Patch patch:route)perPatch.add(supplies(config,List.of(patch),data));
        for(int i=n-1;i>=0;i--)
        {
            SlotCounter counter=new SlotCounter(data);
            for(int j=i+1;j<=n;j++)
            {
                int slots=counter.add(perPatch.get(j-1));
                if(slots>capacity && j>i+1)break;
                int loads=1+count[j];
                int boundary=j==n?0:bank.approachCost(route.get(j-1))+bank.departureCost(route.get(j),config)
                    -Math.min(TravelCosts.arrival(route.get(j),config),TravelCosts.walking(route.get(j-1),route.get(j),config));
                int travel=cost[j]+boundary;
                // Prefer fewer loads, then cheaper banking boundaries, then a fuller first inventory.
                if(loads<count[i] || loads==count[i] && (travel<cost[i] || travel==cost[i] && j>next[i]))
                {count[i]=loads;cost[i]=travel;next[i]=j;occupied[i]=slots;}
                if(slots>capacity)break; // An oversized single-patch load is retained and visibly flagged.
            }
        }
        List<Load> loads=new ArrayList<>();
        for(int i=0;i<n;i=next[i])loads.add(new Load(route.subList(i,next[i]),occupied[i]));
        return new Plan(signature,loads,capacity);
    }
}

package com.classictreerun;

import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.SwingWorker;

/** EDT coordinator: item metadata arrives from the client thread; planning runs off the EDT. */
final class InventoryPreparation
{
    /** Identity distinguishes retries even when both requests contain the same items. */
    static final class ItemRequest
    {
        final Set<Integer> items;
        ItemRequest(Set<Integer> items) { this.items=Set.copyOf(items); }
    }
    private final ClassicTreeRunConfig config;
    private final Runnable changed;
    private Consumer<ItemRequest> request=ids->{ };
    private InventoryItemData data=InventoryItemData.EMPTY;
    private ItemRequest pendingData;
    private String requestedPlan;
    private SwingWorker<InventoryLoadPlanner.Plan,Void> worker;
    private InventoryLoadPlanner.Plan plan;
    private boolean disposed;
    private String error;
    InventoryPreparation(ClassicTreeRunConfig config,Runnable changed) { this.config=config;this.changed=changed; }
    void setRequest(Consumer<ItemRequest> request) { this.request=request;pendingData=null; }
    void accept(ItemRequest source,InventoryItemData incoming)
    {
        if(disposed || source!=pendingData)return;
        pendingData=null;data=data.merge(incoming);changed.run();
    }
    void failed(ItemRequest source)
    {
        if(disposed || source!=pendingData)return;
        if(worker!=null){worker.cancel(false);worker=null;}
        plan=null;requestedPlan=null;
        error="Couldn't read RuneLite item data. Toggle Plan inventory loads off and on to retry.";
        changed.run();
    }
    InventoryLoadPlanner.Plan get() { return plan; }
    InventoryItemData data() { return data; }
    String error() { return error; }
    void update(List<Patch> route)
    {
        if(disposed)return;
        if(!config.loadPlanning())
        {if(worker!=null)worker.cancel(false);worker=null;plan=null;requestedPlan=null;pendingData=null;error=null;return;}
        Set<Integer> items=SupplyPlan.build(config,route).items;
        if(!data.covers(items))
        {
            if(worker!=null)worker.cancel(false);
            plan=null;requestedPlan=null;
            if(pendingData==null || !items.equals(pendingData.items))
            {error=null;pendingData=new ItemRequest(items);request.accept(pendingData);}
            return;
        }
        pendingData=null;
        String signature=InventoryLoadPlanner.signature(config,route,data);
        if(signature.equals(requestedPlan))return;
        if(worker!=null)worker.cancel(false);
        requestedPlan=signature;plan=null;error=null;
        ClassicTreeRunConfig snapshot=LocalRunConfig.snapshot(config);
        List<Patch> patches=List.copyOf(route);InventoryItemData definitions=data;
        worker=new SwingWorker<InventoryLoadPlanner.Plan,Void>()
        {
            @Override protected InventoryLoadPlanner.Plan doInBackground()
            { return InventoryLoadPlanner.plan(snapshot,patches,definitions); }
            @Override protected void done()
            {
                if(disposed || isCancelled() || !signature.equals(requestedPlan))return;
                try { plan=get(); }
                catch(Exception failure){error="Couldn't prepare inventory loads. Change an inventory setting to retry.";}
                changed.run();
            }
        };
        worker.execute();
    }
    void dispose() { disposed=true;pendingData=null;if(worker!=null)worker.cancel(false); }
}

package com.classictreerun;

import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.Map;
import java.util.Properties;
import net.runelite.client.util.Filepath;

/** A plain local file, outside RuneLite's synced configuration. No network access. */
final class LocalPreferences implements ClassicTreeRunPanel.Preferences
{
    private final Filepath file;
    private final Properties values = new Properties();

    LocalPreferences(Filepath file) throws IOException
    {
        this.file = file;
        if (file.exists())
        {
            try (Reader reader = file.openBufferedReader()) { values.load(reader); }
            catch (IllegalArgumentException error) { throw new IOException("Invalid local settings; original file preserved", error); }
        }
    }

    boolean exists() { return file.exists(); }
    public String get(String key) { return values.getProperty(key); }
    public void set(String key, String value)
    {
        java.util.Map<String, String> change = new java.util.HashMap<>();
        change.put(key, value);
        update(change);
    }

    @Override public void update(Map<String, String> changes)
    {
        Properties next = new Properties();
        next.putAll(values);
        changes.forEach((key, value) -> { if (value == null) { next.remove(key); } else { next.setProperty(key, value); } });
        Filepath temporary = null;
        try
        {
            file.getParent().createDirectories();
            temporary = file.getParent().createTempFile("planner-", ".tmp");
            try (Writer writer = temporary.openBufferedWriter())
            {
                next.store(writer, "Farm Run Planner - local data only");
            }
            try { temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException error) { temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING); }
            values.clear();
            values.putAll(next);
        }
        catch (IOException error) { throw new IllegalStateException("Could not save local farming settings. Check folder access and disk space.", error); }
        finally
        {
            if (temporary != null) { try { temporary.deleteIfExists(); } catch (IOException ignored) { /* Old data remains intact. */ } }
        }
    }
}

