    public enum Type
    {
        TREE("Normal tree"), FRUIT("Fruit tree"), HARDWOOD("Hardwood"), CALQUAT("Calquat"),
        ALLOTMENT("Allotment"), FLOWER("Flower"), HERB("Herb"), HOPS("Hops"), BUSH("Bush"),
        CACTUS("Cactus"), SEAWEED("Seaweed"), GRAPE("Grape"), MUSHROOM("Mushroom"),
        BELLADONNA("Belladonna"), HESPORI("Hespori"), ANIMA("Anima"), CRYSTAL("Crystal tree"),
        CELASTRUS("Celastrus"), REDWOOD("Redwood"), CORAL("Coral nursery"), SPIRIT("Spirit tree");
        private final String label;
        Type(String label) { this.label = label; }
        public String toString() { return label; }
    }

    private final Type type;
    private final String location;
    private final String directions;
    private final String gardener;
    private final String requirements;
    private final PatchSite site;

    Patch(Type type, String location, String directions, String gardener, String requirements)
    {
        this.type = type;
        this.location = location;
        this.directions = directions;
        this.gardener = gardener;
        this.requirements = requirements;
        this.site = null;
    }

    Patch(Type type, PatchSite site, String directions, String gardener, String requirements)
    {
        this.type = type;
        this.site = site;
        this.location = site.label;
        this.directions = directions;
        this.gardener = gardener;
        this.requirements = requirements + "; " + site.requirements;
    }

    public boolean isClassic() { return ordinal() < 16; }

    public static java.util.List<Patch> classic()
    {
        return java.util.Arrays.asList(java.util.Arrays.copyOf(values(), 16));
    }

    PatchSite getSite()
    {
        if (site != null) { return site; }
        switch (this)
        {
            case LUMBRIDGE_TREE: return PatchSite.LUMBRIDGE;
            case VARROCK_TREE: return PatchSite.VARROCK;
            case FALADOR_TREE: return PatchSite.FALADOR_TREE;
            case TAVERLEY_TREE: return PatchSite.TAVERLEY;
            case STRONGHOLD_TREE: case STRONGHOLD_FRUIT: return PatchSite.STRONGHOLD;
            case VILLAGE_FRUIT: return PatchSite.VILLAGE;
            case LLETYA_FRUIT: return PatchSite.LLETYA;
            case CATHERBY_FRUIT: return PatchSite.CATHERBY_FRUIT;
            case BRIMHAVEN_FRUIT: return PatchSite.BRIMHAVEN;
            case TAI_BWO_WANNAI_CALQUAT: return PatchSite.CALQUAT;
            case FOSSIL_EAST: case FOSSIL_MIDDLE: case FOSSIL_WEST: return PatchSite.FOSSIL;
            case GUILD_TREE: case GUILD_FRUIT: return PatchSite.GUILD;
            default: throw new IllegalStateException("Missing site: " + this);
        }
    }

    public Type getType() { return type; }
    public String getLocation() { return location; }
    public String getDirections() { return directions; }
    public String getGardener() { return gardener; }
    public String getRequirements() { return requirements; }
    public String getLabel() { return location + " - " + (isClassic() ? type.toString() : directions); }
}

package com.classictreerun;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/** Native cog values use RuneLite storage; snapshots and progress use local files. */
final class PlannerPreferences implements ClassicTreeRunPanel.Preferences
{
    private final ClassicTreeRunPanel.Preferences nativeSettings;
    private final ClassicTreeRunPanel.Preferences local;
    private final Set<String> nativeKeys = ConfigValues.KEYS;
    PlannerPreferences(ClassicTreeRunPanel.Preferences nativeSettings, ClassicTreeRunPanel.Preferences local)
    {
        this.nativeSettings = nativeSettings; this.local = local;
    }
    public String get(String key) { return (nativeKeys.contains(key) ? nativeSettings : local).get(key); }
    public void set(String key, String value)
    {
        Map<String, String> changes = new LinkedHashMap<>(); changes.put(key, value); update(changes);
    }
    @Override public void update(Map<String, String> changes)
    {
        Map<String, String> localChanges = new LinkedHashMap<>();
        Map<String, String> nativeChanges = new LinkedHashMap<>();
        changes.forEach((key, value) -> (nativeKeys.contains(key) ? nativeChanges : localChanges).put(key, value));
        // A local write failure must not partially change the active native configuration.
        if (!localChanges.isEmpty()) { local.update(localChanges); }
        if (!nativeChanges.isEmpty()) { nativeSettings.update(nativeChanges); }
    }
    void initializeCogActions()
    {
        if (nativeSettings.get("editorPreset") == null) { nativeSettings.set("editorPreset", EditorPreset.CURRENT.name()); }
        // Ensure the very first user click has an old value and is distinguishable from initialization.
        for (String key : nativeKeys)
        {
            if (PresetActions.isAction(key) && nativeSettings.get(key) == null) { nativeSettings.set(key, "false"); }
        }
    }
    void importLocalWorkingRun()
    {
        if ("true".equals(local.get("nativeCogV2"))) { return; }
        Map<String, String> imported = new LinkedHashMap<>();
        for (String key : nativeKeys) { String value = local.get(key); if (value != null) { imported.put(key, value); } }
        nativeSettings.update(imported);
        local.set("nativeCogV2", "true");
    }
}

package com.classictreerun;

/** Native cog commands and slot selection. Called on Swing's EDT. */
final class PresetActions
{
    private final ClassicTreeRunConfig config;
    private final ClassicTreeRunPanel.Preferences preferences;
    private final RunSettings settings;
    private final ClassicTreeRunPanel panel;
    private final PresetSlots slots;
    private final PresetTransfer transfer;
    private boolean changingSelection;

    PresetActions(ClassicTreeRunConfig config, ClassicTreeRunPanel.Preferences preferences,
        RunSettings settings, ClassicTreeRunPanel panel)
    {
        this(config, preferences, settings, panel, null);
    }

    PresetActions(ClassicTreeRunConfig config, ClassicTreeRunPanel.Preferences preferences,
        RunSettings settings, ClassicTreeRunPanel panel, PresetTransfer transfer)
    {
        this.config = config; this.preferences = preferences; this.settings = settings; this.panel = panel;
        this.transfer = transfer;
        slots = new PresetSlots(preferences);
    }
    static boolean isAction(String key)
    {
        return "savePresetAction".equals(key) || "deletePresetAction".equals(key)
            || "exportPresetsAction".equals(key) || "importPresetsAction".equals(key);
    }
    static boolean isCommand(String key) { return isAction(key) || "editorPreset".equals(key); }
    static boolean shouldQueue(String key, String oldValue, String newValue, boolean uiThread)
    {
        return isCommand(key) && uiThread && oldValue != null && newValue != null && !oldValue.equals(newValue);
    }
    boolean isChangingSelection() { return changingSelection; }
    private void setSelected(EditorPreset slot)
    {
        changingSelection = true;
        try { preferences.set("editorPreset", slot.name()); }
        finally { changingSelection = false; }
    }
    void syncForRun() { setSelected(slots.find(config.runName())); }

    void apply(String key)
    {
        if (!isCommand(key)) { return; }
        try
        {
            if ("editorPreset".equals(key))
            {
                EditorPreset selected = config.editorPreset();
                if (selected == EditorPreset.CURRENT)
                {
                    panel.setStatus("Current draft kept. Choose an empty slot to create another preset.");
                    return;
                }
                String name = slots.name(selected);
                if (name == null)
                {
                    // A new slot starts as a copy of the current settings; nothing is saved yet.
                    preferences.set("runName", "New preset " + selected.number());
                    panel.presetEditing(null);
                }
                else
                {
                    // Editing a snapshot does not start a new checklist. Only main-tab selection does.
                    new PresetLibrary(preferences).load(name, false);
                    settings.changed("patch_"); settings.changed("autoOptimize"); settings.prepareNow();
                    panel.presetEditing(name);
                }
            }
            else if ("savePresetAction".equals(key))
            {
                settings.changed("patch_");
                EditorPreset saved = slots.save(config.editorPreset(), config.runName(), config);
                setSelected(saved);
                panel.presetSaved(config.runName());
            }
            else if ("deletePresetAction".equals(key))
            {
                slots.delete(config.editorPreset(), config.runName());
                panel.setStatus("Preset deleted. Current run kept; this slot is now empty.");
            }
            else
            {
                if (transfer == null) { throw new IllegalStateException("Local preset backup storage is unavailable."); }
                panel.setStatus("exportPresetsAction".equals(key)
                    ? transfer.exportPresets(config.backupFilename()) : transfer.importPresets(config.backupFilename(), slots));
            }
        }
        catch (IllegalArgumentException | IllegalStateException error) { panel.setStatus(error.getMessage()); }
    }
}

package com.classictreerun;

import com.google.gson.stream.JsonReader;
import com.google.gson.stream.JsonToken;
import com.google.gson.stream.JsonWriter;
import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Properties;
import java.util.Set;

/** Portable saved runs. Character records and active configuration are deliberately excluded. */
final class PresetBackup
{
    static final int MAX_CHARACTERS = 1024 * 1024;
    private static final int MAX_PRESETS = 256;
    private static final String FORMAT = "farm-run-planner-presets";
    private static final Set<String> BOOLEAN_SETTINGS = Set.of("autoOptimize", "hideCompleted", "showDetails",
        "supplyProtection", "supplyTools", "supplyRake", "supplyDibber", "loadPlanning", "loadNotedProtection");
    private static final Set<String> NUMBER_SETTINGS=Set.of("supplyCoins","loadReservedSlots");

    static final class Entry
    {
        final String name;
        final List<Patch> patches;
        final Map<String, String> settings;

        Entry(String name, List<Patch> patches, Map<String, String> settings)
        {
            this.name = PresetLibrary.validName(name);
            this.patches = List.copyOf(patches);
            this.settings = Map.copyOf(settings);
        }

        boolean matches(Entry other)
        {
            return patches.equals(other.patches) && settings.equals(other.settings);
        }

        Properties snapshot(String savedName)
        {
            Properties values = new Properties();
            values.putAll(settings);
            values.setProperty("runName", savedName);
            for (Patch patch : Patch.values())
            {
                values.setProperty("patch_" + patch.name(), Boolean.toString(patches.contains(patch)));
            }
            String order = RouteState.encode(patches);
            values.setProperty("selectionV2", patches.isEmpty() ? "-" : order);
            values.setProperty("order", order);
            values.setProperty("excluded", "");
            for (String gate : new String[]{"trees", "fruit", "hardwood", "calquat", "otherPatches"})
            {
                values.setProperty(gate, "true");
            }
            return values;
        }
    }

    private PresetBackup() { }

    static Entry capture(String name, ClassicTreeRunConfig config)
    {
        return new Entry(name, RouteState.active(config), settings(config));
    }

    private static Map<String, String> settings(ClassicTreeRunConfig config)
    {
        Map<String, String> values = new LinkedHashMap<>();
        values.put("autoOptimize", Boolean.toString(config.autoOptimize()));
        values.put("hideCompleted", Boolean.toString(config.hideCompleted()));
        values.put("showDetails", Boolean.toString(config.showDetails()));
        values.putAll(TravelCosts.settings(config));
        values.putAll(CropChoices.settings(config));
        values.putAll(InventoryLoadPlanner.settings(config));
        return values;
    }

    static String write(List<Entry> presets)
    {
        if (presets.size() > MAX_PRESETS) { throw invalid("A backup can contain at most 256 presets."); }
        StringWriter text = new StringWriter();
        try (JsonWriter writer = new JsonWriter(text))
        {
            writer.setIndent("  ");
            writer.beginObject().name("format").value(FORMAT).name("version").value(3);
            writer.name("presets").beginArray();
            for (Entry preset : presets)
            {
                writer.beginObject().name("name").value(preset.name).name("patches").beginArray();
                for (Patch patch : preset.patches) { writer.value(patch.name()); }
                writer.endArray().name("settings").beginObject();
                // Use a fixed order so exports are easy to compare and edit.
                for (String key : settings(new ClassicTreeRunConfig() { }).keySet())
                {
                    writer.name(key);
                    if (BOOLEAN_SETTINGS.contains(key)) { writer.value(Boolean.parseBoolean(preset.settings.get(key))); }
                    else if (NUMBER_SETTINGS.contains(key)) { writer.value(Integer.parseInt(preset.settings.get(key))); }
                    else { writer.value(preset.settings.get(key)); }
                }
                writer.endObject().endObject();
            }
            writer.endArray().endObject();
        }
        catch (IOException error) { throw new IllegalStateException("Could not prepare the preset backup.", error); }
        String result = text.toString() + "\n";
        if (result.getBytes(StandardCharsets.UTF_8).length > MAX_CHARACTERS)
        { throw invalid("Preset backups must be smaller than 1 MB."); }
        return result;
    }

    static List<Entry> read(String text)
    {
        if (text.length() > MAX_CHARACTERS) { throw invalid("Preset backups must be smaller than 1 MB."); }
        try (JsonReader reader = new JsonReader(new StringReader(text)))
        {
            reader.setLenient(false);
            Set<String> fields = new HashSet<>();
            List<Entry> presets = new ArrayList<>();
            int version = 0;
            reader.beginObject();
            while (reader.hasNext())
            {
                String key = uniqueField(reader, fields);
                switch (key)
                {
                    case "format":
                        if (!FORMAT.equals(string(reader))) { throw invalid("This file is not a Farm Run Planner preset backup."); }
                        break;
                    case "version":
                        if (reader.peek() != JsonToken.NUMBER) { throw invalid("This preset backup version is not supported."); }
                        String encodedVersion=reader.nextString();
                        if (!("1".equals(encodedVersion) || "2".equals(encodedVersion) || "3".equals(encodedVersion)))
                        { throw invalid("This preset backup version is not supported."); }
                        version=Integer.parseInt(encodedVersion);
                        break;
                    case "presets":
                        Set<String> names = new HashSet<>();
                        reader.beginArray();
                        while (reader.hasNext())
                        {
                            if (presets.size() == MAX_PRESETS) { throw invalid("A backup can contain at most 256 presets."); }
                            Entry entry = readEntry(reader);
                            if (!names.add(entry.name)) { throw invalid("The backup contains duplicate preset names."); }
                            presets.add(entry);
                        }
                        reader.endArray();
                        break;
                    default: throw invalid("The backup contains an unrecognized field.");
                }
            }
            reader.endObject();
            if (!fields.equals(Set.of("format", "version", "presets")) || reader.peek() != JsonToken.END_DOCUMENT)
            { throw invalid("The preset backup is incomplete or contains extra data."); }
            List<Entry> normalized=new ArrayList<>();
            for(Entry entry:presets)
            {
                if(!entry.settings.keySet().equals(keysForVersion(version)))throw invalid("The preset settings do not match the backup version.");
                Map<String,String> values=new LinkedHashMap<>(settings(new ClassicTreeRunConfig() { }));
                values.putAll(entry.settings);
                normalized.add(new Entry(entry.name,entry.patches,values));
            }
            return normalized;
        }
        catch (IOException | IllegalStateException error)
        { throw new IllegalArgumentException("The preset backup is not valid JSON in the expected format.", error); }
    }

    private static Entry readEntry(JsonReader reader) throws IOException
    {
        Set<String> fields = new HashSet<>();
        String name = null;
        List<Patch> patches = new ArrayList<>();
        Map<String, String> values = new LinkedHashMap<>();
        reader.beginObject();
        while (reader.hasNext())
        {
            switch (uniqueField(reader, fields))
            {
                case "name": name = PresetLibrary.validName(string(reader)); break;
                case "patches":
                    Set<Patch> unique = new HashSet<>();
                    reader.beginArray();
                    while (reader.hasNext())
                    {
                        Patch patch;
                        try { patch = Patch.valueOf(string(reader)); }
                        catch (IllegalArgumentException error) { throw invalid("The backup contains an unknown patch."); }
                        if (!unique.add(patch)) { throw invalid("A preset contains a duplicate patch."); }
                        patches.add(patch);
                    }
                    reader.endArray();
                    break;
                case "settings":
                    Set<String> keys = new HashSet<>();
                    Map<String, String> allowed = settings(new ClassicTreeRunConfig() { });
                    reader.beginObject();
                    while (reader.hasNext())
                    {
                        String key = uniqueField(reader, keys);
                        if (!allowed.containsKey(key)) { throw invalid("The backup contains an unsupported preset setting."); }
                        if (BOOLEAN_SETTINGS.contains(key))
                        {
                            if (reader.peek() != JsonToken.BOOLEAN) { throw invalid("A preset setting must be true or false."); }
                            values.put(key, Boolean.toString(reader.nextBoolean()));
                        }
                        else if (NUMBER_SETTINGS.contains(key))
                        {
                            if(reader.peek()!=JsonToken.NUMBER)throw invalid("The inventory setting must be a whole number.");
                            String value=reader.nextString();
                            if(key.startsWith("load"))InventoryLoadPlanner.validate(key,value);else CropChoices.validate(key,value);
                            values.put(key,value);
                        }
                        else
                        {
                            String value = string(reader);
                            if(key.startsWith("crop") || key.startsWith("supply"))CropChoices.validate(key,value);
                            else if(key.startsWith("load"))InventoryLoadPlanner.validate(key,value);
                            else validateTravel(key, value);
                            values.put(key, value);
                        }
                    }
                    reader.endObject();
                    if (!keys.equals(keysForVersion(3)) && !keys.equals(keysForVersion(2)) && !keys.equals(keysForVersion(1)))
                    { throw invalid("A preset is missing required settings."); }
                    break;
                default: throw invalid("A preset contains an unrecognized field.");
            }
        }
        reader.endObject();
        if (!fields.equals(Set.of("name", "patches", "settings"))) { throw invalid("A preset is missing required fields."); }
        return new Entry(name, patches, values);
    }

    private static Set<String> keysForVersion(int version)
    {
        Set<String> keys=new HashSet<>(settings(new ClassicTreeRunConfig() { }).keySet());
        if(version<3)keys.removeIf(key->key.startsWith("load"));
        if(version<2)keys.removeIf(key->key.startsWith("crop") || key.startsWith("supply"));
        return keys;
    }

    private static void validateTravel(String key, String value)
    {
        try
        {
            switch (key)
            {
                case "faladorTravel": ClassicTreeRunConfig.FaladorTravel.valueOf(value); break;
                case "taverleyTravel": ClassicTreeRunConfig.TaverleyTravel.valueOf(value); break;
                case "strongholdTravel": ClassicTreeRunConfig.StrongholdTravel.valueOf(value); break;
                case "catherbyTravel": ClassicTreeRunConfig.CatherbyTravel.valueOf(value); break;
                case "brimhavenTravel": ClassicTreeRunConfig.BrimhavenTravel.valueOf(value); break;
                case "calquatTravel": ClassicTreeRunConfig.CalquatTravel.valueOf(value); break;
                case "fossilTravel": ClassicTreeRunConfig.FossilTravel.valueOf(value); break;
                case "guildTravel": ClassicTreeRunConfig.GuildTravel.valueOf(value); break;
                default: throw invalid("The backup contains an unsupported travel setting.");
            }
        }
        catch (IllegalArgumentException error) { throw invalid("The backup contains an unknown travel option."); }
    }

    private static String uniqueField(JsonReader reader, Set<String> fields) throws IOException
    {
        String key = reader.nextName();
        if (!fields.add(key)) { throw invalid("The backup contains a duplicate field."); }
        return key;
    }

    private static String string(JsonReader reader) throws IOException
    {
        if (reader.peek() != JsonToken.STRING) { throw invalid("A backup field must contain text."); }
        return reader.nextString();
    }

    private static IllegalArgumentException invalid(String message) { return new IllegalArgumentException(message); }
}

package com.classictreerun;

import java.awt.Dimension;
import java.util.function.Consumer;
import javax.swing.*;

/** The main tab selects runs; all creation and management live in the native cog. */
final class PresetControls extends JPanel
{
    PresetControls(ClassicTreeRunConfig config, ClassicTreeRunPanel.Preferences preferences, Runnable loaded,
        String selectedName, Consumer<String> selected, Consumer<String> status)
    {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        PresetLibrary library = new PresetLibrary(preferences);
        JLabel label = new JLabel("Choose your run"); add(label);
        JComboBox<String> names = new JComboBox<>(library.names().toArray(new String[0]));
        DefaultListCellRenderer renderer = new DefaultListCellRenderer();
        renderer.putClientProperty("html.disable", Boolean.TRUE);
        names.setRenderer(renderer); // Treat custom names as text, including names starting with <html>.
        names.setName("savedPresets");
        // A placeholder avoids silently presenting the first saved preset as the active run.
        if (library.contains(selectedName)) { names.setSelectedItem(selectedName); }
        else if (library.contains(config.runName())) { names.setSelectedItem(config.runName()); }
        else { names.setSelectedIndex(-1); }
        names.setToolTipText("Load a saved run with a fresh checklist. Click Start run to filter bank supplies. Create and save presets in the plugin cog.");
        names.setMaximumSize(new Dimension(Integer.MAX_VALUE, names.getPreferredSize().height));
        names.addActionListener(event -> {
            String name = (String) names.getSelectedItem();
            if (name == null) { return; }
            try
            {
                library.load(name);
                selected.accept(name);
                loaded.run();
                status.accept("Loaded: " + name + ". Click Start run for the bank supplies filter.");
            }
            catch (IllegalArgumentException | IllegalStateException error) { status.accept(error.getMessage()); }
        });
        add(names);
        for (java.awt.Component child : getComponents()) { ((JComponent) child).setAlignmentX(LEFT_ALIGNMENT); }
    }
}

package com.classictreerun;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;

/** Explicit snapshots: draft edits never overwrite a saved preset. */
final class PresetLibrary
{
    static final String KEY = "localPresetsV2";
    private final ClassicTreeRunPanel.Preferences preferences;
    private final Properties saved;
    PresetLibrary(ClassicTreeRunPanel.Preferences preferences)
    {
        this.preferences = preferences;
        saved = decode(preferences.get(KEY));
    }
    Set<String> names() { return new TreeSet<>(saved.stringPropertyNames()); }
    boolean contains(String name) { return name != null && saved.containsKey(name); }
    static String validName(String name)
    {
        String clean = name.trim();
        if (clean.isEmpty() || clean.length() > 60 || clean.chars().anyMatch(Character::isISOControl))
        { throw new IllegalArgumentException("Use a name of 1–60 characters, without line breaks."); }
        return clean;
    }

    void save(String name, ClassicTreeRunConfig config)
    {
        save(name, config, null, java.util.Collections.emptyMap());
    }

    void save(String name, ClassicTreeRunConfig config, String replacedName, Map<String, String> extras)
    {
        String clean = validName(name);
        Properties snapshot = snapshot(config);
        snapshot.setProperty("runName", clean);
        Properties next = new Properties();
        next.putAll(saved);
        if (replacedName != null && !replacedName.equals(clean)) { next.remove(replacedName); }
        next.setProperty(clean, encode(snapshot));
        Map<String, String> changes = new LinkedHashMap<>();
        changes.put(KEY, encode(next));
        changes.put("runName", clean);
        changes.putAll(extras);
        preferences.update(changes);
        saved.clear(); saved.putAll(next);
    }

    private static Properties snapshot(ClassicTreeRunConfig config)
    {
        Properties snapshot = new Properties();
        ConfigValues.read(config).forEach((key,value) -> { if (snapshotKey(key)) { snapshot.setProperty(key,value); } });
        return snapshot;
    }

    void seedStarters(ClassicTreeRunConfig config)
    {
        if ("true".equals(preferences.get("startersV2"))) { return; }
        Properties next = new Properties(); next.putAll(saved);
        for (RunPreset preset : new RunPreset[]{RunPreset.HERBS, RunPreset.TREES, RunPreset.HERBS_AND_TREES})
        {
            if (next.containsKey(preset.toString())) { continue; }
            Properties template = snapshot(config);
            Set<Patch> patches = preset.starter(java.util.Collections.emptySet());
            for (Patch patch : Patch.values()) { template.setProperty("patch_" + patch.name(), Boolean.toString(patches.contains(patch))); }
            template.setProperty("selectionV2", RouteState.encode(patches));
            template.setProperty("excluded", ""); template.setProperty("order", "");
            template.setProperty("runName", preset.toString());
            for (String gate : new String[]{"trees", "fruit", "hardwood", "calquat", "otherPatches"}) { template.setProperty(gate, "true"); }
            next.setProperty(preset.toString(), encode(template));
        }
        Map<String, String> changes = new LinkedHashMap<>(); changes.put(KEY, encode(next)); changes.put("startersV2", "true");
        preferences.update(changes); saved.clear(); saved.putAll(next);
    }

    void load(String name) { load(name, true); }

    void load(String name, boolean resetCompletion)
    {
        if (!contains(name)) { throw new IllegalArgumentException("Choose a saved preset first."); }
        Properties snapshot = decode(saved.getProperty(name));
        Map<String, String> changes = new LinkedHashMap<>();
        changes.putAll(CropChoices.settings(new ClassicTreeRunConfig() { }));
        changes.putAll(InventoryLoadPlanner.settings(new ClassicTreeRunConfig() { }));
        snapshot.forEach((key, value) -> { if (snapshotKey((String) key)) { changes.put((String) key, (String) value); } });
        changes.put("runName", name);
        // Loading a run starts a fresh checklist; completion is never part of a preset.
        if (resetCompletion) { changes.put(ClassicTreeRunPanel.PROGRESS_KEY, "");changes.put(InventoryLoadPlanner.BANKS_KEY,""); }
        preferences.update(changes);
    }

    void delete(String name) { delete(name, java.util.Collections.emptyMap()); }

    void delete(String name, Map<String, String> extras)
    {
        Properties next = new Properties(); next.putAll(saved); next.remove(name);
        Map<String, String> changes = new LinkedHashMap<>(extras); changes.put(KEY, encode(next));
        preferences.update(changes);
        saved.clear(); saved.putAll(next);
    }

    java.util.List<Patch> patches(String name)
    {
        if(!contains(name))return java.util.Collections.emptyList();
        return RouteState.active(config(name));
    }

    ClassicTreeRunConfig config(String name)
    {
        if (!contains(name)) { throw new IllegalArgumentException("Choose a saved preset first."); }
        Properties snapshot=decode(saved.getProperty(name));
        ClassicTreeRunPanel.Preferences values=new ClassicTreeRunPanel.Preferences(){
            public String get(String key){return snapshot.getProperty(key);}
            public void set(String key,String value){throw new UnsupportedOperationException("Read-only preset");}
        };
        return new LocalRunConfig(values);
    }

    void merge(Map<String, Properties> additions, Map<String, String> extras)
    {
        Properties next = new Properties();
        next.putAll(saved);
        additions.forEach((name, snapshot) -> next.setProperty(name, encode(snapshot)));
        Map<String, String> changes = new LinkedHashMap<>(extras);
        changes.put(KEY, encode(next));
        preferences.update(changes);
        saved.clear();
        saved.putAll(next);
    }

    private static boolean snapshotKey(String key)
    {
        return key.startsWith("patch_") || key.startsWith("crop") || key.startsWith("supply") || key.startsWith("load") || key.endsWith("Travel") || "runName".equals(key)
            || "autoOptimize".equals(key) || "showDetails".equals(key) || "hideCompleted".equals(key)
            || "order".equals(key) || "selectionV2".equals(key) || "excluded".equals(key)
            || "trees".equals(key) || "fruit".equals(key) || "hardwood".equals(key)
            || "calquat".equals(key) || "otherPatches".equals(key);
    }

    private static Properties decode(String text)
    {
        Properties result = new Properties();
        if (text == null) { return result; }
        try { result.load(new StringReader(text)); }
        catch (IOException | IllegalArgumentException error) { throw new IllegalStateException("Saved presets could not be read; original file preserved", error); }
        return result;
    }
    private static String encode(Properties values)
    {
        try { StringWriter writer = new StringWriter(); values.store(writer, null); return writer.toString(); }
        catch (IOException impossible) { throw new IllegalStateException(impossible); }
    }
}

package com.classictreerun;

import java.io.IOException;
import java.io.StringReader;
import java.io.StringWriter;
import java.util.EnumMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Properties;
import java.util.List;
import java.util.Set;
import java.util.HashSet;

/** Local, stable mappings from native editor slot IDs to saved snapshot names. */
final class PresetSlots
{
    static final String KEY = "editorSlotsV1";
    private final ClassicTreeRunPanel.Preferences preferences;
    private final Map<EditorPreset, String> slots = new EnumMap<>(EditorPreset.class);

    PresetSlots(ClassicTreeRunPanel.Preferences preferences)
    {
        this.preferences = preferences;
        Properties stored = new Properties();
        try
        {
            if (preferences.get(KEY) != null) { stored.load(new StringReader(preferences.get(KEY))); }
        }
        catch (IOException | IllegalArgumentException error) { throw new IllegalStateException("Couldn't read local preset slots; original file preserved", error); }
        PresetLibrary library = new PresetLibrary(preferences);
        for (EditorPreset slot : EditorPreset.values())
        {
            String name = stored.getProperty(slot.name());
            if (slot != EditorPreset.CURRENT && library.contains(name) && !slots.containsValue(name)) { slots.put(slot, name); }
        }
        Map<EditorPreset, String> before = new EnumMap<>(slots);
        // Adopt earlier named presets without replacing or deleting their snapshots.
        for (String name : library.names())
        {
            if (slots.containsValue(name)) { continue; }
            EditorPreset free = firstFree(slots);
            if (free == null) { break; }
            slots.put(free, name);
        }
        if (preferences.get(KEY) == null || !before.equals(slots) || stored.size() != slots.size())
        { preferences.set(KEY, encode(slots)); }
        EditorPreset.publish(slots);
    }

    String name(EditorPreset slot) { return slots.get(slot); }
    EditorPreset find(String name)
    {
        for (Map.Entry<EditorPreset, String> entry : slots.entrySet()) { if (entry.getValue().equals(name)) { return entry.getKey(); } }
        return EditorPreset.CURRENT;
    }

    EditorPreset save(EditorPreset selected, String name, ClassicTreeRunConfig config)
    {
        String clean = PresetLibrary.validName(name);
        PresetLibrary library = new PresetLibrary(preferences);
        EditorPreset target = selected;
        if (target == EditorPreset.CURRENT)
        {
            target = find(clean);
            if (target == EditorPreset.CURRENT) { target = firstFree(slots); }
        }
        if (target == null) { throw new IllegalArgumentException("All 32 editor slots are used. Delete an unused preset or edit an existing slot."); }
        String previous = slots.get(target);
        if (library.contains(clean) && !clean.equals(previous))
        { throw new IllegalArgumentException("That name is already saved. Choose its slot or use a different name."); }
        Map<EditorPreset, String> next = new EnumMap<>(slots); next.put(target, clean);
        Map<String, String> extras = new LinkedHashMap<>(); extras.put(KEY, encode(next));
        library.save(clean, config, previous, extras);
        slots.clear(); slots.putAll(next); EditorPreset.publish(slots);
        return target;
    }

    void delete(EditorPreset selected, String currentName)
    {
        String target = selected == EditorPreset.CURRENT ? currentName : slots.get(selected);
        PresetLibrary library = new PresetLibrary(preferences);
        if (!library.contains(target)) { throw new IllegalArgumentException("Choose a saved preset slot to delete."); }
        Map<EditorPreset, String> next = new EnumMap<>(slots); next.values().removeIf(target::equals);
        Map<String, String> extras = new LinkedHashMap<>(); extras.put(KEY, encode(next));
        library.delete(target, extras);
        slots.clear(); slots.putAll(next); EditorPreset.publish(slots);
    }

    String importPresets(List<PresetBackup.Entry> entries)
    {
        PresetLibrary library = new PresetLibrary(preferences);
        Map<EditorPreset, String> next = new EnumMap<>(slots);
        Map<String, Properties> additions = new LinkedHashMap<>();
        Set<String> reserved = new HashSet<>(library.names());
        Set<String> incomingNames = new HashSet<>();
        for (PresetBackup.Entry entry : entries) { reserved.add(entry.name); incomingNames.add(entry.name); }
        int skipped = 0, renamed = 0;
        for (PresetBackup.Entry entry : entries)
        {
            String name = entry.name;
            if (library.contains(name))
            {
                if (entry.matches(PresetBackup.capture(name, library.config(name)))) { skipped++; continue; }
                int copy = 1;
                do
                {
                    String suffix = copy == 1 ? " (imported)" : " (imported " + copy + ")";
                    int end = Math.min(entry.name.length(), 60 - suffix.length());
                    if (end > 0 && Character.isHighSurrogate(entry.name.charAt(end - 1))) { end--; }
                    name = entry.name.substring(0, end).stripTrailing() + suffix;
                    copy++;
                    if (!incomingNames.contains(name) && library.contains(name)
                        && entry.matches(PresetBackup.capture(name, library.config(name))))
                    { name = null; skipped++; break; }
                }
                while (reserved.contains(name));
                if (name == null) { continue; }
                renamed++;
            }
            EditorPreset free = firstFree(next);
            if (free == null)
            { throw new IllegalArgumentException("Not enough free preset slots for this import. Delete an unused preset and try again. No presets were changed."); }
            reserved.add(name);
            next.put(free, name);
            additions.put(name, entry.snapshot(name));
        }
        if (!additions.isEmpty())
        {
            library.merge(additions, Map.of(KEY, encode(next)));
            slots.clear();
            slots.putAll(next);
            EditorPreset.publish(slots);
        }
        return "Imported " + additions.size() + " presets; " + skipped + " identical copies skipped; "
            + renamed + " renamed to keep existing presets. Reopen the cog to refresh its preset list.";
    }

    private static EditorPreset firstFree(Map<EditorPreset, String> values)
    {
        for (EditorPreset slot : EditorPreset.values()) { if (slot != EditorPreset.CURRENT && !values.containsKey(slot)) { return slot; } }
        return null;
    }
    private static String encode(Map<EditorPreset, String> values)
    {
        Properties data = new Properties(); values.forEach((slot, name) -> data.setProperty(slot.name(), name));
        try { StringWriter out = new StringWriter(); data.store(out, null); return out.toString(); }
        catch (IOException impossible) { throw new IllegalStateException(impossible); }
    }
}

package com.classictreerun;

import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Reads and writes preset-only backups inside the plugin's local backup directory. */
final class PresetTransfer
{
    private final Filepath directory;
    private final ClassicTreeRunPanel.Preferences preferences;

    PresetTransfer(Filepath directory, ClassicTreeRunPanel.Preferences preferences)
    {
        this.directory = directory;
        this.preferences = preferences;
    }

    String exportPresets(String filename)
    {
        Filepath file = file(filename);
        PresetLibrary library = new PresetLibrary(preferences);
        List<PresetBackup.Entry> entries = new ArrayList<>();
        for (String name : library.names()) { entries.add(PresetBackup.capture(name, library.config(name))); }
        String backup = PresetBackup.write(entries);
        Filepath temporary = null;
        try
        {
            directory.createDirectories();
            temporary = directory.createTempFile("preset-backup-", ".tmp");
            try (Writer writer = temporary.openBufferedWriter()) { writer.write(backup); }
            try { temporary.moveTo(file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING); }
            catch (AtomicMoveNotSupportedException error) { temporary.moveTo(file, StandardCopyOption.REPLACE_EXISTING); }
        }
        catch (IOException error) { throw new IllegalStateException("Could not export presets. Check folder access and disk space.", error); }
        finally
        {
            if (temporary != null)
            {
                try { temporary.deleteIfExists(); } catch (IOException ignored) { /* Keep the existing backup. */ }
            }
        }
        return "Exported " + entries.size() + " presets to preset-backups/" + file.getFileName() + ".";
    }

    String importPresets(String filename, PresetSlots slots)
    {
        Filepath file = file(filename);
        if (!file.isFile()) { throw new IllegalArgumentException("Put the JSON file in the plugin's preset-backups folder, then try Import presets again."); }
        StringBuilder text = new StringBuilder();
        try
        {
            if (file.size() > PresetBackup.MAX_CHARACTERS) { throw new IllegalArgumentException("Preset backups must be smaller than 1 MB."); }
            try (Reader reader = file.openBufferedReader())
            {
                char[] buffer = new char[4096];
                int count;
                while ((count = reader.read(buffer)) != -1)
                {
                    if (text.length() + count > PresetBackup.MAX_CHARACTERS)
                    { throw new IllegalArgumentException("Preset backups must be smaller than 1 MB."); }
                    text.append(buffer, 0, count);
                }
            }
        }
        catch (IOException error) { throw new IllegalStateException("Could not read the preset backup. Existing presets were kept.", error); }
        return slots.importPresets(PresetBackup.read(text.toString()));
    }

    private Filepath file(String filename)
    {
        String clean = filename.trim();
        if (!clean.matches("[A-Za-z0-9][A-Za-z0-9._-]{0,75}\\.json") || clean.contains(".."))
        { throw new IllegalArgumentException("Use a simple .json filename with letters, numbers, hyphens or underscores; no folder path."); }
        return directory.joinSegment(clean);
    }
}

package com.classictreerun;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CancellationException;
import java.util.function.BooleanSupplier;

/** Exact independent travel groups; bounded fallback only for unsupported large cost models. */
final class RouteOptimizer
{
    private RouteOptimizer() { }

    static List<Patch> optimize(List<Patch> patches, int[] entry, int[][] travel)
    { return optimize(patches,entry,travel,()->false); }

    static List<Patch> optimize(List<Patch> patches, int[] entry, int[][] travel, BooleanSupplier cancelled)
    {
        checkCancelled(cancelled);
        int n = patches.size();
        if (entry.length != n || travel.length != n) { throw new IllegalArgumentException("Invalid route dimensions"); }
        if (n == 0) { return new ArrayList<>(); }
        for (int[] row : travel) { if (row.length != n) { throw new IllegalArgumentException("Invalid cost matrix"); } }
        List<List<Integer>> groups = independentGroups(entry,travel,cancelled);
        if(groups!=null && groups.size()>1)
        {
            List<Patch> result=new ArrayList<>();
            for(List<Integer> group:groups)
            {
                checkCancelled(cancelled);
                int m=group.size();int[] localEntry=new int[m];int[][] localTravel=new int[m][m];
                List<Patch> localPatches=new ArrayList<>();
                for(int i=0;i<m;i++)
                {
                    int original=group.get(i);localPatches.add(patches.get(original));localEntry[i]=entry[original];
                    for(int j=0;j<m;j++)localTravel[i][j]=travel[original][group.get(j)];
                }
                result.addAll(exactRoute(localPatches,localEntry,localTravel,cancelled));
            }
            return result;
        }
        if (n > 16) { return largeRoute(patches, entry, travel, cancelled); }
        return exactRoute(patches,entry,travel,cancelled);
    }

    /**
     * Cross-group travel must equal the next patch's entry cost, and all other edges
     * may only save cost. Any route's within-group chains can then be joined without
     * increasing cost. Solving each group exactly and concatenating is globally optimal.
     * Removing patches cannot enlarge these groups. See docs/route-optimality.md.
     */
    private static List<List<Integer>> independentGroups(int[] entry,int[][] travel,BooleanSupplier cancelled)
    {
        int n=entry.length;
        for(int i=0;i<n;i++)for(int j=0;j<n;j++)
            if(i!=j && travel[i][j]>entry[j])return null;
        List<List<Integer>> groups=new ArrayList<>();boolean[] used=new boolean[n];
        for(int start=0;start<n;start++)if(!used[start])
        {
            checkCancelled(cancelled);
            List<Integer> group=new ArrayList<>();group.add(start);used[start]=true;
            for(int at=0;at<group.size();at++)
            {
                int from=group.get(at);
                for(int to=0;to<n;to++)if(!used[to] && (travel[from][to]<entry[to] || travel[to][from]<entry[from]))
                {
                    used[to]=true;group.add(to);
                    if(group.size()>16)return null;
                }
            }
            Collections.sort(group);groups.add(group);
        }
        return groups;
    }

    private static List<Patch> exactRoute(List<Patch> patches,int[] entry,int[][] travel,BooleanSupplier cancelled)
    {
        int n=patches.size();
        int size = 1 << n;
        int[] best = new int[size * n];
        byte[] previous = new byte[size * n];
        Arrays.fill(best, Integer.MAX_VALUE);
        Arrays.fill(previous, (byte) -1);
        for (int i = 0; i < n; i++) { best[(1 << i) * n + i] = entry[i]; }
        for (int mask = 1; mask < size; mask++)
        {
            if((mask & 127)==1)checkCancelled(cancelled);
            for (int last = 0; last < n; last++)
            {
                int cost = best[mask * n + last];
                if (cost == Integer.MAX_VALUE) { continue; }
                for (int next = 0; next < n; next++)
                {
                    if ((mask & (1 << next)) != 0) { continue; }
                    int index = (mask | (1 << next)) * n + next;
                    int candidate = cost + travel[last][next];
                    if (candidate < best[index])
                    {
                        best[index] = candidate;
                        previous[index] = (byte) last;
                    }
                }
            }
        }
        int mask = size - 1;
        // Prefer the existing later endpoint on ties, preserving the default guild finish where possible.
        int last = n - 1;
        for (int i = n - 2; i >= 0; i--)
        {
            if (best[mask * n + i] < best[mask * n + last]) { last = i; }
        }
        List<Patch> result = new ArrayList<>();
        while (last >= 0)
        {
            result.add(patches.get(last));
            int prev = previous[mask * n + last];
            mask ^= 1 << last;
            last = prev;
        }
        Collections.reverse(result);
        return result;
    }

    private static List<Patch> largeRoute(List<Patch> patches, int[] entry, int[][] travel, BooleanSupplier cancelled)
    {
        int n = patches.size();
        List<Integer> best = new ArrayList<>();
        for (int i = 0; i < n; i++) { best.add(i); }
        int bestScore = score(best, entry, travel); // Never return a worse route than the user's order.
        for (int start = 0; start < n; start++)
        {
            checkCancelled(cancelled);
            boolean[] used = new boolean[n];
            List<Integer> route = new ArrayList<>();
            int last = start;
            used[last] = true;
            route.add(last);
            while (route.size() < n)
            {
                int next = -1;
                for (int j = 0; j < n; j++)
                {
                    if (!used[j] && (next < 0 || travel[last][j] < travel[last][next])) { next = j; }
                }
                used[next] = true;
                route.add(next);
                last = next;
            }
            int candidate = score(route, entry, travel);
            if (candidate < bestScore) { best = route; bestScore = candidate; }
        }
        // Score each directed relocation from its changed edges, including first-stop entry.
        for (int pass = 0; pass < Math.min(n, 100); pass++)
        {
            checkCancelled(cancelled);
            int bestFrom = -1, bestTo = -1;
            int improvedScore = bestScore;
            for (int from = 0; from < n; from++)
            {
                int stop = best.get(from);
                int before = from > 0 ? best.get(from - 1) : -1;
                int after = from + 1 < n ? best.get(from + 1) : -1;
                int removed = before < 0 ? entry[after] - entry[stop] - travel[stop][after]
                    : -travel[before][stop] + (after < 0 ? 0 : travel[before][after] - travel[stop][after]);
                for (int to = 0; to < n; to++)
                {
                    // Index the route with 'from' removed, without copying or rescoring every edge.
                    int left = to > 0 ? best.get(to - 1 < from ? to - 1 : to) : -1;
                    int right = to < n - 1 ? best.get(to < from ? to : to + 1) : -1;
                    int inserted = left < 0 ? entry[stop] + travel[stop][right] - entry[right]
                        : travel[left][stop] + (right < 0 ? 0 : travel[stop][right] - travel[left][right]);
                    int cost = bestScore + removed + inserted;
                    if (cost < improvedScore) { bestFrom = from; bestTo = to; improvedScore = cost; }
                }
            }
            if (bestFrom < 0) { break; }
            Integer stop = best.remove(bestFrom);
            best.add(bestTo, stop);
            bestScore = improvedScore;
        }
        List<Patch> result = new ArrayList<>();
        for (int index : best) { result.add(patches.get(index)); }
        return result;
    }

    private static void checkCancelled(BooleanSupplier cancelled)
    { if(cancelled.getAsBoolean())throw new CancellationException("Route preparation superseded"); }

    private static int score(List<Integer> route, int[] entry, int[][] travel)
    {
        int score = entry[route.get(0)];
        for (int i = 1; i < route.size(); i++) { score += travel[route.get(i - 1)][route.get(i)]; }
        return score;
    }
}

package com.classictreerun;

import java.util.ArrayList;
import java.util.Collection;
import java.util.EnumSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;

/** Pure model: no client state, game actions, clocks, or network access. */
final class RouteState
{
    private final Set<Patch> completed = EnumSet.noneOf(Patch.class);

    static List<Patch> ordered(String csv)
    {
        Set<Patch> result = new LinkedHashSet<>(parse(csv));
        java.util.Collections.addAll(result, Patch.values());
        return new ArrayList<>(result);
    }

    static Set<Patch> parse(String csv)
    {
        Set<Patch> result = new LinkedHashSet<>();
        if (csv != null)
        {
            for (String token : csv.split(","))
            {
                try { result.add(Patch.valueOf(token.trim())); }
                catch (IllegalArgumentException ignored) { /* Ignore stale or unknown IDs. */ }
            }
        }
        return result;
    }

    static String encode(Collection<Patch> patches)
    {
        return patches.stream().map(Enum::name).collect(Collectors.joining(","));
    }

    static boolean enabled(Patch patch, ClassicTreeRunConfig config)
    {
        // Legacy profiles/presets never silently opt into new patches after catalogue expansion.
        if (config.selection().isEmpty() ? !patch.isClassic() : !parse(config.selection()).contains(patch)) { return false; }
        if (parse(config.excluded()).contains(patch)) { return false; }
        return categoryEnabled(patch,config);
    }

    private static boolean categoryEnabled(Patch patch, ClassicTreeRunConfig config)
    {
        switch (patch.getType())
        {
            case TREE: return config.trees();
            case FRUIT: return config.fruit();
            case HARDWOOD: return config.hardwood();
            case CALQUAT: return config.calquat();
            default: return config.otherPatches();
        }
    }

    static List<Patch> active(ClassicTreeRunConfig config)
    {
        String selection=config.selection();
        Set<Patch> selected=selection.isEmpty()?EnumSet.copyOf(Patch.classic()):parse(selection);
        selected.removeAll(parse(config.excluded()));
        return ordered(config.order()).stream().filter(p -> selected.contains(p) && categoryEnabled(p,config)).collect(Collectors.toList());
    }

    void load(String csv) { completed.clear(); completed.addAll(parse(csv)); }
    String save() { return encode(completed); }
    boolean isDone(Patch patch) { return completed.contains(patch); }
    void setDone(Patch patch, boolean done)
    {
        if (done) { completed.add(patch); } else { completed.remove(patch); }
    }
    void reset() { completed.clear(); }
    int count(List<Patch> route) { return (int) route.stream().filter(this::isDone).count(); }
    Patch next(List<Patch> route) { return route.stream().filter(p -> !isDone(p)).findFirst().orElse(null); }
}

package com.classictreerun;

import java.util.EnumSet;
import java.util.LinkedHashSet;
import java.util.Set;

/** Starter templates and legacy slot identifiers for one-time import. */
public enum RunPreset
{
    CUSTOM("Named / current run"),
    HERBS("Herbs"),
    TREES("Trees"),
    HERBS_AND_TREES("Herbs + trees"),
    CUSTOM_1("Custom preset 1"),
    CUSTOM_2("Custom preset 2");

    private final String label;
    RunPreset(String label) { this.label = label; }
    @Override public String toString() { return label; }

    String key() { return "presetSelection_" + name(); }

    Set<Patch> starter(Set<Patch> current)
    {
        if (this == CUSTOM || this == CUSTOM_1 || this == CUSTOM_2) { return new LinkedHashSet<>(current); }
        Set<Patch> selected = EnumSet.noneOf(Patch.class);
        for (Patch patch : Patch.values())
        {
            boolean herb = patch.getType() == Patch.Type.HERB;
            boolean tree = treeType(patch.getType());
            if (this == HERBS && herb || this == TREES && tree || this == HERBS_AND_TREES && (herb || tree))
            {
                selected.add(patch);
            }
        }
        return selected;
    }

    private static boolean treeType(Patch.Type type)
    {
        switch (type)
        {
            case TREE: case FRUIT: case HARDWOOD: case CALQUAT: case CRYSTAL: case CELASTRUS: case REDWOOD: return true;
            default: return false; // Spirit trees are usually planted once, so are opt-in edits.
        }
    }
}

package com.classictreerun;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.SwingWorker;
import javax.swing.Timer;

/** Bridges local cog settings to a prepared run. All methods are called on Swing's EDT. */
final class RunSettings
{
    static final String MIGRATED = "nativeSettingsV1";
    private final ClassicTreeRunConfig config;
    private final ClassicTreeRunPanel.Preferences preferences;
    private final ClassicTreeRunPanel panel;
    private final Timer delay;
    private Set<Patch> observed;
    private boolean dirty;
    private boolean disposed;
    private int version;
    private SwingWorker<List<Patch>,Void> worker;

    RunSettings(ClassicTreeRunConfig config, ClassicTreeRunPanel.Preferences preferences, ClassicTreeRunPanel panel)
    {
        this.config = config;
        this.preferences = preferences;
        this.panel = panel;
        delay = new Timer(200, event -> prepareNow());
        delay.setRepeats(false);
        if (!"true".equals(preferences.get(MIGRATED)))
        {
            Set<Patch> legacy = new LinkedHashSet<>(RouteState.active(config));
            Set<Patch> nativeSelection = NativePatchSelection.read(config);
            // Preserve patch flags imported from the earlier native settings editor.
            if (!nativeSelection.equals(new LinkedHashSet<>(Patch.classic()))) { legacy = nativeSelection; }
            writeNativeSelection(legacy);
            preferences.set(MIGRATED, "true");
        }
        observed = new LinkedHashSet<>(NativePatchSelection.read(config));
        mirrorSelection();
        queue();
    }

    void changed(String key)
    {
        if (disposed) { return; }
        if (key.startsWith("patch_"))
        {
            Set<Patch> selected = NativePatchSelection.read(config);
            if (!selected.equals(observed))
            {
                observed = new LinkedHashSet<>(selected);
                mirrorSelection();
                queue();
            }
        }
        else if (key.endsWith("Travel") || "autoOptimize".equals(key)) { queue(); }
        panel.reload();
    }

    void select(Set<Patch> selected)
    {
        writeNativeSelection(selected);
        observed = new LinkedHashSet<>(selected);
        mirrorSelection();
        queue();
    }

    private void writeNativeSelection(Set<Patch> selected)
    {
        Map<String, String> changes = new java.util.LinkedHashMap<>();
        for (Patch patch : Patch.values()) { changes.put("patch_" + patch.name(), Boolean.toString(selected.contains(patch))); }
        preferences.update(changes);
    }

    private void mirrorSelection()
    {
        Set<Patch> excluded = new LinkedHashSet<>(Arrays.asList(Patch.values()));
        excluded.removeAll(observed);
        Map<String, String> changes = new java.util.LinkedHashMap<>();
        changes.put("selectionV2", observed.isEmpty() ? "-" : RouteState.encode(observed));
        changes.put("excluded", RouteState.encode(excluded));
        for (String gate : new String[]{"trees", "fruit", "hardwood", "calquat", "otherPatches"}) { changes.put(gate, "true"); }
        preferences.update(changes);
    }

    private void queue()
    {
        panel.setRoutePreparing(true);
        if(worker!=null){worker.cancel(false);worker=null;}
        version++;
        dirty = true;
        panel.setStatus("Preparing your run...");
        delay.restart();
    }

    void prepareNow()
    {
        if(disposed)return;
        if (!dirty) { panel.reload(); return; }
        dirty = false;
        delay.stop();
        if (!config.autoOptimize()) { panel.setRoutePreparing(false);panel.setStatus(""); panel.reload(); return; }
        int requestedVersion = version;
        List<Patch> selected = RouteState.active(config);
        TravelCosts costs = new TravelCosts(selected, config);
        worker=new SwingWorker<List<Patch>, Void>()
        {
            protected List<Patch> doInBackground() { return RouteOptimizer.optimize(selected, costs.entry, costs.travel,this::isCancelled); }
            protected void done()
            {
                if (disposed || isCancelled() || requestedVersion != version) { return; }
                worker=null;
                panel.setRoutePreparing(false);
                try
                {
                    List<Patch> order = new ArrayList<>(get());
                    for (Patch patch : RouteState.ordered(config.order())) { if (!order.contains(patch)) { order.add(patch); } }
                    preferences.set("order", RouteState.encode(order));
                    panel.setStatus("");
                }
                catch (Exception error) { panel.setStatus("Couldn't reorder this run. Your patches are saved; change a travel setting to retry."); }
                panel.reload();
            }
        };
        worker.execute();
    }

    void dispose()
    {
        disposed = true;
        version++;
        delay.stop();
        if(worker!=null){worker.cancel(false);worker=null;}
    }
}

package com.classictreerun;

import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

/** Versioned preference format. Names are encoded so punctuation cannot corrupt records. */
final class SavedRuns
{
    static final String KEY = "savedRunsV1";

    private SavedRuns() { }

    static Map<String, Set<Patch>> decode(String value)
    {
        Map<String, Set<Patch>> runs = new LinkedHashMap<>();
        if (value == null) { return runs; }
        for (String record : value.split(";"))
        {
            int split = record.indexOf(':');
            if (split < 0) { continue; }
            try
            {
                String name = new String(Base64.getUrlDecoder().decode(record.substring(0, split)), StandardCharsets.UTF_8);
                if (!name.trim().isEmpty()) { runs.put(name, RouteState.parse(record.substring(split + 1))); }
            }
            catch (IllegalArgumentException ignored) { /* Keep valid records if one is damaged. */ }
        }
        return runs;
    }

    static String encode(Map<String, Set<Patch>> runs)
    {
        StringBuilder result = new StringBuilder();
        runs.forEach((name, patches) ->
        {
            if (result.length() > 0) { result.append(';'); }
            result.append(Base64.getUrlEncoder().withoutPadding().encodeToString(name.getBytes(StandardCharsets.UTF_8)))
                .append(':').append(RouteState.encode(patches));
        });
        return result.toString();
    }
}

package com.classictreerun;

import java.util.Set;

/** Client-thread state for the ordinary bank's display callback. */
final class SupplyBankFilter
{
    private Set<Integer> items=Set.of();
    private boolean armed, seenBank;
    void start(SupplyPlan plan) { items=plan.items;armed=!items.isEmpty();seenBank=false; }
    void clear() { items=Set.of();armed=false;seenBank=false; }
    boolean active() { return armed; }
    void bankVisible(boolean visible)
    {
        if(visible)seenBank=true;
        else if(seenBank)clear();
    }
    void filter(String callback,boolean bankOpen,int[] stack,int size,int itemId,boolean placeholder)
    {
        if(!armed || !bankOpen || size<1 || size>stack.length)return;
        if("bankBuildTab".equals(callback)){stack[size-1]=1;return;}
        if(!"bankSearchFilter".equals(callback) || size<2)return;
        // Preserve other search/tag filters. No placeholder stands in for an item the player owns.
        if(placeholder || !items.contains(itemId))stack[size-2]=0;
    }
}

