package com.classictreerun;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.gameval.ItemID;

/** Display-only packing list for the chosen crops. Does not inspect or change game actions. */
public final class SupplyPlan
{
    public enum Compost
    {
        NONE, COMPOST, SUPERCOMPOST, ULTRACOMPOST, BOTTOMLESS;
        @Override public String toString()
        {
            if(this==BOTTOMLESS)return "Bottomless compost bucket";
            return this==NONE ? "No compost" : name().substring(0,1)+name().substring(1).toLowerCase(java.util.Locale.ROOT);
        }
    }

    static final class Requirement
    {
        final String label;
        final int item, quantity;
        final boolean notes, notedOnly, reusable;
        final Set<Integer> alternatives;
        Requirement(String label, int item, int quantity, boolean notes, Integer... alternatives)
        { this(label,item,quantity,notes,false,false,alternatives); }
        private Requirement(String label,int item,int quantity,boolean notes,boolean notedOnly,boolean reusable,Integer... alternatives)
        {
            this.label=label; this.item=item; this.quantity=quantity; this.notes=notes;this.notedOnly=notedOnly;this.reusable=reusable;
            java.util.HashSet<Integer> ids=new java.util.HashSet<>(List.of(alternatives));
            ids.add(item); this.alternatives=Set.copyOf(ids);
        }
        static Requirement once(String label,int item,int quantity,Integer... alternatives)
        { return new Requirement(label,item,quantity,false,false,true,alternatives); }
    }

    final List<Requirement> requirements;
    final Set<Integer> items;
    final List<String> reminders;

    private SupplyPlan(List<Requirement> requirements, List<String> reminders)
    {
        this.requirements=List.copyOf(requirements); this.reminders=List.copyOf(reminders);
        java.util.HashSet<Integer> ids=new java.util.HashSet<>();
        for(Requirement requirement:requirements)
        {
            ids.addAll(requirement.alternatives);
            // Let players find an empty bucket to fill, without counting it as usable compost.
            if(requirement.item==ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED)ids.add(ItemID.BOTTOMLESS_COMPOST_BUCKET);
        }
        items=Set.copyOf(ids);
    }

    static SupplyPlan build(ClassicTreeRunConfig config, List<Patch> patches)
    {
        List<Requirement> result=new ArrayList<>();
        List<String> reminders=new ArrayList<>();
        Map<Integer,Requirement> planting=new LinkedHashMap<>(), payments=new LinkedHashMap<>();
        boolean seeds=false, secateurs=false, grapes=false, belladonna=false, coral=false, axe=false;
        int compost=0;
        for(Patch patch:patches)
        {
            Patch.Type type=patch.getType();
            CropChoices.Crop crop=CropChoices.forType(type,config);
            boolean tree=Set.of(Patch.Type.TREE,Patch.Type.FRUIT,Patch.Type.HARDWOOD,Patch.Type.CALQUAT,
                Patch.Type.SPIRIT,Patch.Type.CRYSTAL,Patch.Type.CELASTRUS,Patch.Type.REDWOOD).contains(type);
            if(crop.item!=-1)
            {
                String name=crop.label+(tree ? " sapling" : type==Patch.Type.CORAL ? " frag" : " seed");
                if(type==Patch.Type.SEAWEED)name="Seaweed spore";
                if(type==Patch.Type.MUSHROOM)name="Mushroom spore";
                if(type==Patch.Type.HERB && crop.item==ItemID.VILLAGE_RARE_TUBER)name="Gout tuber";
                add(planting,name,crop.item,crop.quantity,false);
                seeds|=!tree && type!=Patch.Type.CORAL && crop.item!=ItemID.VILLAGE_RARE_TUBER;
                if(config.supplyProtection() && !patch.getGardener().startsWith("No "))
                {
                    for(CropChoices.Payment payment:crop.payments)
                        add(payments,payment.label+" (optional protection)",payment.item,payment.quantity,true);
                }
                boolean immune=Set.of(Patch.Type.CORAL,Patch.Type.ANIMA,Patch.Type.HESPORI,Patch.Type.GRAPE).contains(type)
                    || crop.item==ItemID.POISONIVY_BUSH_SEED;
                // Paid tree protection prevents disease. Compost remains useful for variable-yield crops.
                boolean paidTree=tree && type!=Patch.Type.CELASTRUS && config.supplyProtection() && !crop.payments.isEmpty();
                if(!immune && !paidTree)compost++;
                if(type==Patch.Type.GRAPE)add(planting,"Saltpetre",ItemID.HOSIDIUS_SALTPETRE,1,false);
            }
            secateurs|=Set.of(Patch.Type.HERB,Patch.Type.ALLOTMENT,Patch.Type.HOPS,Patch.Type.BUSH,
                Patch.Type.GRAPE,Patch.Type.CELASTRUS).contains(type);
            grapes|=type==Patch.Type.GRAPE; belladonna|=type==Patch.Type.BELLADONNA;
            coral|=type==Patch.Type.CORAL;
            axe|=Set.of(Patch.Type.TREE,Patch.Type.FRUIT,Patch.Type.HARDWOOD,Patch.Type.SPIRIT,
                Patch.Type.CRYSTAL,Patch.Type.CELASTRUS,Patch.Type.REDWOOD).contains(type);
        }
        result.addAll(planting.values());
        if(compost>0 && config.supplyCompost()!=Compost.NONE)
        {
            if(config.supplyCompost()==Compost.BOTTOMLESS)
            {
                result.add(Requirement.once("Filled bottomless bucket (presence only)",ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED,1));
                reminders.add("Bottomless bucket: check its compost type and charges for "+compost+" remaining patches. Charges are not counted.");
            }
            else
            {
                int item=config.supplyCompost()==Compost.COMPOST ? ItemID.BUCKET_COMPOST
                    : config.supplyCompost()==Compost.SUPERCOMPOST ? ItemID.BUCKET_SUPERCOMPOST : ItemID.BUCKET_ULTRACOMPOST;
                result.add(new Requirement(config.supplyCompost().name().toLowerCase(java.util.Locale.ROOT)+" buckets",item,compost,false));
            }
        }
        if(!patches.isEmpty())
        {
            if(config.supplyTools())
            {
                result.add(Requirement.once("Spade",ItemID.SPADE,1));
                if(secateurs)result.add(Requirement.once("Secateurs (magic recommended)",ItemID.FAIRY_ENCHANTED_SECATEURS,1,ItemID.SECATEURS));
                if(grapes)result.add(Requirement.once("Gardening trowel",ItemID.GARDENING_TROWEL,1));
                if(axe)result.add(Requirement.once("Axe (optional if paying for removal)",ItemID.BRONZE_AXE,1,
                    ItemID.IRON_AXE,ItemID.STEEL_AXE,ItemID.BLACK_AXE,ItemID.MITHRIL_AXE,ItemID.ADAMANT_AXE,
                    ItemID.RUNE_AXE,ItemID.DRAGON_AXE,ItemID.INFERNAL_AXE,ItemID.INFERNAL_AXE_EMPTY,ItemID.CRYSTAL_AXE,
                    ItemID.BRONZE_AXE_2H,ItemID.IRON_AXE_2H,ItemID.STEEL_AXE_2H,ItemID.BLACK_AXE_2H,
                    ItemID.MITHRIL_AXE_2H,ItemID.ADAMANT_AXE_2H,ItemID.RUNE_AXE_2H,ItemID.DRAGON_AXE_2H,ItemID.CRYSTAL_AXE_2H));
            }
            if(config.supplyRake())result.add(Requirement.once("Rake",ItemID.RAKE,1));
            if(config.supplyDibber() && seeds)result.add(Requirement.once("Seed dibber",ItemID.DIBBER,1));
            if(config.supplyCoins()>0)result.add(Requirement.once("Coins (your budget)",ItemID.COINS,config.supplyCoins()));
            if(axe)reminders.add("Pack an axe if chopping trees yourself; bring extra coins for gardener removal and fares.");
            if(belladonna)reminders.add("Wear suitable gloves before harvesting belladonna.");
            if(coral)reminders.add("Coral nurseries require diving equipment or a medallion of the deep.");
            if(patches.stream().anyMatch(p->p.getType()==Patch.Type.HESPORI))reminders.add("Bring your own Hespori combat equipment.");
        }
        // Unnoted consumables are allocated first; noted protection cannot satisfy a planting requirement.
        result.addAll(payments.values());
        return new SupplyPlan(result,reminders);
    }

    private static void add(Map<Integer,Requirement> rows,String label,int item,int quantity,boolean notes)
    {
        Requirement previous=rows.get(item);
        rows.put(item,new Requirement(label,item,quantity+(previous==null?0:previous.quantity),notes));
    }

    SupplyPlan forInventory(boolean notedPayments,InventoryItemData data)
    {
        List<Requirement> rows=new ArrayList<>();
        for(Requirement row:requirements)
        {
            InventoryItemData.ItemInfo info=data.get(row.item);
            boolean notedOnly=notedPayments && row.notes && info.noteable && !info.stackable;
            rows.add(new Requirement(row.label,row.item,row.quantity,row.notes,notedOnly,row.reusable,row.alternatives.toArray(new Integer[0])));
        }
        return new SupplyPlan(rows,reminders);
    }

    /** Allocates shared supplies once (e.g. compost used both on a patch and as payment). */
    List<Long> carried(SupplySnapshot snapshot)
    {
        Map<Integer,Long> plain=new LinkedHashMap<>(snapshot.plain), notes=new LinkedHashMap<>(snapshot.notes);
        List<Long> counts=new ArrayList<>();
        for(Requirement row:requirements)
        {
            long available=0;
            for(int id:row.alternatives)
            {
                if(!row.notedOnly)available+=plain.getOrDefault(id,0L);
                if(row.notes)available+=notes.getOrDefault(id,0L);
            }
            counts.add(available);
            long needed=row.quantity;
            if(row.notes)needed=consume(notes,row.alternatives,needed);
            if(!row.notedOnly)consume(plain,row.alternatives,needed);
        }
        return Collections.unmodifiableList(counts);
    }

    private static long consume(Map<Integer,Long> counts,Set<Integer> ids,long needed)
    {
        for(int id:ids)
        {
            long used=Math.min(needed,counts.getOrDefault(id,0L));
            counts.put(id,counts.getOrDefault(id,0L)-used);needed-=used;
        }
        return needed;
    }
}

package com.classictreerun;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

/** Ephemeral inventory/equipment counts; never saved or uploaded. */
final class SupplySnapshot
{
    static final SupplySnapshot UNKNOWN=new SupplySnapshot(false,Map.of(),Map.of());
    final boolean known;
    final Map<Integer,Long> plain, notes;
    SupplySnapshot(boolean known,Map<Integer,Long> plain,Map<Integer,Long> notes)
    { this.known=known;this.plain=Map.copyOf(plain);this.notes=Map.copyOf(notes); }

    static SupplySnapshot read(ItemManager items,ItemContainer inventory,ItemContainer equipment)
    { return read(items::getItemComposition,inventory,equipment); }

    static SupplySnapshot read(java.util.function.IntFunction<ItemComposition> definitions,ItemContainer inventory,ItemContainer equipment)
    {
        if(inventory==null || equipment==null)return UNKNOWN;
        Map<Integer,Long> plain=new HashMap<>(),notes=new HashMap<>();
        for(ItemContainer container:new ItemContainer[]{inventory,equipment})
            for(Item item:container.getItems())
            {
                if(item.getId()<0 || item.getQuantity()<=0)continue;
                ItemComposition definition=definitions.apply(item.getId());
                if(definition.getPlaceholderTemplateId()!=-1)continue;
                boolean noted=definition.getNote()!=-1;
                int id=noted?definition.getLinkedNoteId():item.getId();
                (noted?notes:plain).merge(id,(long)item.getQuantity(),Long::sum);
            }
        return new SupplySnapshot(true,plain,notes);
    }
}

package com.classictreerun;

import java.util.List;

/** Relative travel-effort scores, NOT measured seconds, tiles, or live pathfinding. */
final class TravelCosts
{
    final int[] entry;
    final int[][] travel;

    static java.util.Map<String,String> settings(ClassicTreeRunConfig config)
    {
        java.util.Map<String,String> values=new java.util.LinkedHashMap<>();
        values.put("faladorTravel",config.faladorTravel().name());
        values.put("taverleyTravel",config.taverleyTravel().name());
        values.put("strongholdTravel",config.strongholdTravel().name());
        values.put("catherbyTravel",config.catherbyTravel().name());
        values.put("brimhavenTravel",config.brimhavenTravel().name());
        values.put("calquatTravel",config.calquatTravel().name());
        values.put("fossilTravel",config.fossilTravel().name());
        values.put("guildTravel",config.guildTravel().name());
        return values;
    }

    TravelCosts(List<Patch> patches, ClassicTreeRunConfig config)
    {
        int n = patches.size();
        entry = new int[n];
        travel = new int[n][n];
        for (int i = 0; i < n; i++)
        {
            entry[i] = arrival(patches.get(i), config);
            for (int j = 0; j < n; j++)
            {
                travel[i][j] = Math.min(arrival(patches.get(j), config), walking(patches.get(i), patches.get(j), config));
                // Leaving the Stronghold fruit patch gives convenient access to its spirit tree.
                if (patches.get(i) == Patch.STRONGHOLD_FRUIT && patches.get(j) == Patch.VILLAGE_FRUIT)
                {
                    travel[i][j] = Math.min(travel[i][j], 24);
                }
                if (patches.get(i) == Patch.STRONGHOLD_FRUIT && patches.get(j) == Patch.BRIMHAVEN_FRUIT
                    && config.brimhavenTravel() == ClassicTreeRunConfig.BrimhavenTravel.SPIRIT_TREE)
                {
                    travel[i][j] = Math.min(travel[i][j], 16);
                }
            }
        }
    }

    static int arrival(Patch p, ClassicTreeRunConfig c)
    {
        switch (p)
        {
            case LUMBRIDGE_TREE: return 22;
            case VARROCK_TREE: return 30;
            case FALADOR_TREE: return c.faladorTravel() == ClassicTreeRunConfig.FaladorTravel.RING_OF_WEALTH ? 8 : 25;
            case TAVERLEY_TREE:
                switch (c.taverleyTravel())
                {
                    case BALLOON: return 35; // Includes reaching an origin, not just the flight.
                    case FALADOR_TELEPORT: return 65;
                    default: return 20;
                }
            case STRONGHOLD_TREE: return c.strongholdTravel() == ClassicTreeRunConfig.StrongholdTravel.SLAYER_RING ? 12 : 38;
            case STRONGHOLD_FRUIT: return 32;
            case VILLAGE_FRUIT: return 45;
            case LLETYA_FRUIT: return 12;
            case CATHERBY_FRUIT: return c.catherbyTravel() == ClassicTreeRunConfig.CatherbyTravel.CATHERBY_TELEPORT ? 22 : 60;
            case BRIMHAVEN_FRUIT:
                switch (c.brimhavenTravel())
                {
                    case CATHERBY_CHARTER: return arrival(Patch.CATHERBY_FRUIT, c) + 45;
                    case SPIRIT_TREE: return 35;
                    case ARDOUGNE_BOAT: return 65;
                    default: return 25;
                }
            case TAI_BWO_WANNAI_CALQUAT:
                switch (c.calquatTravel())
                {
                    case FAIRY_RING_CKR: return 70;
                    case WALK_FROM_BRIMHAVEN: return arrival(Patch.BRIMHAVEN_FRUIT, c) + 90;
                    default: return 12;
                }
            case FOSSIL_EAST:
            case FOSSIL_MIDDLE:
            case FOSSIL_WEST:
                return (c.fossilTravel() == ClassicTreeRunConfig.FossilTravel.DIGSITE_BARGE ? 65 : 55)
                    + (p == Patch.FOSSIL_MIDDLE ? 1 : 0);
            case GUILD_TREE:
            case GUILD_FRUIT:
                switch (c.guildTravel())
                {
                    case FARMING_CAPE: return p == Patch.GUILD_TREE ? 22 : 20;
                    case SPIRIT_TREE: return p == Patch.GUILD_TREE ? 25 : 12;
                    default: return p == Patch.GUILD_TREE ? 25 : 35;
                }
            default:
                switch (p.getSite())
                {
                    case GUILD: return p == Patch.GUILD_HESPORI ? 40 : 30;
                    case FALADOR_FARM: case ARDOUGNE_FARM: return 12;
                    case HOSIDIUS_FARM: case PHASMATYS: return 25;
                    case TROLL: case WEISS: return 12;
                    case UNDERWATER: return 85;
                    case ANGLERS: return 110;
                    case CONCH: return 65;
                    case CORAL: return 90;
                    case ENTRANA: return 90;
                    case PRIF: return 35;
                    case KASTORI: return 50;
                    case NEMUS: case AUBURNVALE: return 55;
                    case CATHERBY_FARM: return c.catherbyTravel() == ClassicTreeRunConfig.CatherbyTravel.CATHERBY_TELEPORT ? 18 : 45;
                    default: return 45;
                }
        }
    }

    static int walking(Patch from, Patch to, ClassicTreeRunConfig c)
    {
        // This local connection includes the walk to the docks and the charter journey.
        if (from == Patch.CATHERBY_FRUIT && to == Patch.BRIMHAVEN_FRUIT
            && c.brimhavenTravel() == ClassicTreeRunConfig.BrimhavenTravel.CATHERBY_CHARTER) { return 45; }
        if (from == Patch.STRONGHOLD_TREE && to == Patch.STRONGHOLD_FRUIT) { return 18; }
        if (from == Patch.STRONGHOLD_FRUIT && to == Patch.STRONGHOLD_TREE) { return 18; }
        if (from == Patch.GUILD_TREE && to == Patch.GUILD_FRUIT || from == Patch.GUILD_FRUIT && to == Patch.GUILD_TREE) { return 18; }
        if (from.getSite() == PatchSite.FOSSIL && to.getSite() == PatchSite.FOSSIL)
        {
            return Math.abs(from.ordinal() - to.ordinal()) * 2;
        }
        if (from != to && from.getSite() == to.getSite())
        {
            // Generic same-site grouping; scores are intentionally not stated as walking seconds.
            if (from.getSite() == PatchSite.GUILD) { return from == Patch.GUILD_HESPORI || to == Patch.GUILD_HESPORI ? 18 : 8; }
            if (from.getSite() == PatchSite.KASTORI || from.getSite() == PatchSite.BRIMHAVEN) { return 18; }
            return 3;
        }
        if (from == Patch.BRIMHAVEN_FRUIT && to == Patch.TAI_BWO_WANNAI_CALQUAT
            && c.calquatTravel() == ClassicTreeRunConfig.CalquatTravel.WALK_FROM_BRIMHAVEN) { return 90; }
        return Integer.MAX_VALUE;
    }

    static String walkingInstruction(Patch from, Patch to, ClassicTreeRunConfig c)
    {
        if (from == null || walking(from, to, c) >= arrival(to, c)) { return null; }
        if (from == Patch.CATHERBY_FRUIT && to == Patch.BRIMHAVEN_FRUIT
            && c.brimhavenTravel() == ClassicTreeRunConfig.BrimhavenTravel.CATHERBY_CHARTER)
        {
            return TravelGuide.catherbyCharterInstructions();
        }
        if (from.getSite() == PatchSite.FOSSIL && to.getSite() == PatchSite.FOSSIL)
        {
            return "Stay at the Fossil Island hardwood cluster and walk to the "
                + (to == Patch.FOSSIL_EAST ? "east" : to == Patch.FOSSIL_MIDDLE ? "middle" : "west") + " patch.";
        }
        if (from == Patch.STRONGHOLD_TREE && to == Patch.STRONGHOLD_FRUIT) { return "Walk north-east from the Stronghold normal tree to the fruit patch east of the spirit tree."; }
        if (from == Patch.STRONGHOLD_FRUIT && to == Patch.STRONGHOLD_TREE) { return "Walk south-west from the Stronghold fruit patch to the normal tree patch near the Slayer Cave."; }
        if (from.getSite() == PatchSite.GUILD && to == Patch.GUILD_TREE) { return "Stay in the Farming Guild; walk to the west wing normal tree patch."; }
        if (from.getSite() == PatchSite.GUILD && to == Patch.GUILD_FRUIT) { return "Stay in the Farming Guild; walk to the north wing fruit patch (85 Farming)."; }
        if (from.getSite() == to.getSite()) { return "Stay at " + to.getLocation() + "; walk to " + to.getDirections() + "."; }
        if(from==Patch.BRIMHAVEN_FRUIT && to==Patch.TAI_BWO_WANNAI_CALQUAT
            && c.calquatTravel()==ClassicTreeRunConfig.CalquatTravel.WALK_FROM_BRIMHAVEN)
        {return "From Brimhaven fruit patch, run south towards Tai Bwo Wannai to the calquat patch north of the village.";}
        return null;
    }
}

package com.classictreerun;

final class TravelGuide
{
    private TravelGuide() { }

    static String instructions(Patch patch, ClassicTreeRunConfig c)
    {
        switch (patch)
        {
            case LUMBRIDGE_TREE:
                return "Lumbridge Teleport spell/tablet; leave the castle grounds and go west to the patch. Use the spell/tablet, not the slow Home Teleport.";
            case VARROCK_TREE:
                return "Varrock Teleport to the city centre; run north into the castle courtyard. If your default teleport is the Grand Exchange, select the city-centre destination.";
            case FALADOR_TREE:
                return c.faladorTravel() == ClassicTreeRunConfig.FaladorTravel.RING_OF_WEALTH
                    ? "Ring of wealth: Falador Park. Go to the tree patch inside the park."
                    : "Falador Teleport spell/tablet; run east into Falador Park to the tree patch.";
            case TAVERLEY_TREE:
                switch (c.taverleyTravel())
                {
                    case BALLOON: return "Use an unlocked balloon route to Taverley; the patch is near the landing. Requires Enlightened Journey, the route unlock, appropriate fuel and balloon weight restrictions. Access a balloon first (e.g. Crafting Guild).";
                    case FALADOR_TELEPORT: return "Falador Teleport; travel north-west to Taverley, using the western wall shortcut if available, then go to the tree patch.";
                    default: return "Break a Taverley teleport tablet (house tablet + scroll of redirection; 10 Construction). Walk to the tree patch. Alternatively teleport outside a house actually located in Taverley.";
                }
            case STRONGHOLD_TREE:
                return c.strongholdTravel() == ClassicTreeRunConfig.StrongholdTravel.SLAYER_RING
                    ? "Slayer ring: Stronghold Slayer Cave. Leave the cave entrance area for the nearby normal tree patch."
                    : "Use any accessible spirit tree (e.g. Grand Exchange) to Tree Gnome Stronghold; run south-west to the normal tree patch.";
            case STRONGHOLD_FRUIT:
                return "From the Stronghold normal tree, run north-east to the fruit patch east of the spirit tree. If arriving independently, use a spirit tree to Tree Gnome Stronghold.";
            case VILLAGE_FRUIT:
                return "From an accessible spirit tree (the Stronghold tree is convenient), select Tree Gnome Village. Squeeze through the loose railing and follow Elkoy out of the maze; the fruit patch is outside, west of the maze. Alternative: fairy ring CIQ.";
            case LLETYA_FRUIT:
                return "Teleport crystal or eternal teleport crystal: Lletya. Walk to the village fruit patch. Lletya access is obtained during Mourning's End Part I; this is not the Prifddinas crystal-tree patch.";
            case CATHERBY_FRUIT:
                return c.catherbyTravel() == ClassicTreeRunConfig.CatherbyTravel.CATHERBY_TELEPORT
                    ? "Catherby Teleport (Lunar spell, tablet or configured POH portal/nexus); run east along the shore to the fruit patch near the fishing spots."
                    : "Camelot Teleport to Camelot (not the Seers' bank destination); run south-east through Catherby, then east along the shore to the fruit patch.";
            case BRIMHAVEN_FRUIT:
                switch (c.brimhavenTravel())
                {
                    case CATHERBY_CHARTER:
                        return catherbyCharterInstructions() + " If you are elsewhere, first reach Catherby using "
                            + (c.catherbyTravel() == ClassicTreeRunConfig.CatherbyTravel.CATHERBY_TELEPORT
                                ? "Catherby Teleport (spell, tablet or POH)."
                                : "Camelot Teleport to Camelot, then run south-east to Catherby.")
                            + " You do not need to visit the fruit patch if it is not in your run.";
                    case SPIRIT_TREE: return "Use an accessible spirit tree to your grown Brimhaven spirit tree; walk to the fruit patch north of the town. Requires your own planted Brimhaven spirit tree.";
                    case ARDOUGNE_BOAT: return "Ardougne Teleport; run to the docks and pay Captain Barnaby for passage to Brimhaven. Walk to the nearby fruit patch; carry the fare.";
                    default: return "Break a Brimhaven teleport tablet (house tablet + scroll of redirection; 40 Construction); run north to the fruit patch. Alternatively teleport outside your Brimhaven house.";
                }
            case TAI_BWO_WANNAI_CALQUAT:
                switch (c.calquatTravel())
                {
                    case FAIRY_RING_CKR: return "Fairy ring CKR; travel north to the calquat patch north of Tai Bwo Wannai village. Requires fairy ring access and a staff unless exempt.";
                    case WALK_FROM_BRIMHAVEN: return "From Brimhaven fruit patch, run south towards Tai Bwo Wannai; stop at the calquat patch north of the village. If elsewhere, first reach Brimhaven. This saves a scroll but adds running.";
                    default: return "Use a Tai bwo wannai teleport scroll; walk north to the calquat patch. The scroll requires completion of Tai Bwo Wannai Trio.";
                }
            case FOSSIL_EAST:
            case FOSSIL_MIDDLE:
            case FOSSIL_WEST:
                String entry = c.fossilTravel() == ClassicTreeRunConfig.FossilTravel.DIGSITE_BARGE
                    ? "Digsite pendant: Digsite; use the barge's quick-travel to Fossil Island, then run north-west from the camp to the hardwood cluster. Requires Bone Voyage."
                    : "Digsite pendant: Fossil Island (House on the Hill, unlocked destination); use the unlocked mushtree to Mushroom Meadow, then run south-east to the hardwood cluster. Requires Bone Voyage and these transport unlocks.";
                return entry + " If already at the cluster, move to the "
                    + (patch == Patch.FOSSIL_EAST ? "east" : patch == Patch.FOSSIL_MIDDLE ? "middle" : "west")
                    + " patch. Each of the three patches has its own checkbox.";
            case GUILD_TREE:
                return guild(c) + " Go to the west wing normal tree patch (65 Farming).";
            case GUILD_FRUIT:
                return "If already in the Farming Guild, walk to the north wing fruit patch (85 Farming). Otherwise: " + guild(c);
            default:
                String travel = patch.getSite() == PatchSite.GUILD ? guild(c) : patch.getSite().travel;
                if (patch.getSite() == PatchSite.CATHERBY_FARM && c.catherbyTravel() == ClassicTreeRunConfig.CatherbyTravel.CAMELOT_TELEPORT)
                {
                    travel = "Camelot Teleport to Camelot; run east towards Catherby and the farming patches north of town.";
                }
                return travel + " At the location: " + patch.getDirections() + ".";
        }
    }

    static String catherbyCharterInstructions()
    {
        return "From Catherby fruit patch, walk west along the shore to the charter ship at Catherby docks. "
            + charterToBrimhaven();
    }

    static String catherbyBankCharterInstructions()
    { return "From Catherby bank, walk to the charter ship at Catherby docks. "+charterToBrimhaven(); }

    private static String charterToBrimhaven()
    { return "Choose Charter on a Trader Crewmember, select Brimhaven, then walk to the nearby fruit patch. Bring coins for the fare."; }

    private static String guild(ClassicTreeRunConfig c)
    {
        switch (c.guildTravel())
        {
            case FARMING_CAPE: return "Farming cape teleport to the Farming Guild (99 Farming).";
            case SPIRIT_TREE: return "Use an accessible spirit tree to your grown Farming Guild spirit tree; north wing access is required.";
            default: return "Skills necklace: Farming Guild; enter the guild.";
        }
    }
}

package com.classictreerun;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
