import javax.swing.SwingUtilities;
import org.junit.Test;
import static org.junit.Assert.*;

public class SidebarTest
{
    @Test public void runTabContainsOnlyPreparedRouteAndProgressControls() throws Exception
    {
        SwingUtilities.invokeAndWait(() ->
        {
            ConfigFixture f = new ConfigFixture();
            f.set("loadPlanning","false");
            f.set("selectionV2", "TROLL_HERB,WEISS_HERB");
            f.set("runName", "Daily herbs");
            ClassicTreeRunPanel panel = new ClassicTreeRunPanel(f.config, f);
            assertNotNull(find(panel, "TROLL_HERB"));
            assertNotNull(find(panel, "WEISS_HERB"));
            assertNull(find(panel, "LUMBRIDGE_TREE"));
            for (String removed : new String[]{"editRoute", "saveRun", "optimizeRun", "typeFilter", "patchSearch"})
            {
                assertNull("Setup control leaked into the run tab: " + removed, find(panel, removed));
            }
            capture(panel);
        });
    }

    @Test public void completionPersistsAndResetPreservesConfiguration() throws Exception
    {
        SwingUtilities.invokeAndWait(() ->
        {
            ConfigFixture f = new ConfigFixture();
            f.set("selectionV2", "TROLL_HERB,WEISS_HERB");
            f.set("hideCompleted", "true");
            ClassicTreeRunPanel panel = new ClassicTreeRunPanel(f.config, f);
            panel.setConfirmReset(false);
            ((AbstractButton) find(panel, "TROLL_HERB")).doClick();
            assertNull(find(panel, "TROLL_HERB"));
            assertTrue(f.get(ClassicTreeRunPanel.PROGRESS_KEY).contains("TROLL_HERB"));
            ClassicTreeRunPanel reopened = new ClassicTreeRunPanel(f.config, f);
            assertNull(find(reopened, "TROLL_HERB"));
            ((AbstractButton) find(panel, "resetRun")).doClick();
            assertEquals("", f.get(ClassicTreeRunPanel.PROGRESS_KEY));
            assertEquals("TROLL_HERB,WEISS_HERB", f.config.selection());
            assertNotNull(find(panel, "TROLL_HERB"));
        });
    }

    @Test public void returningToTabPreparesLatestSettings() throws Exception
    {
        SwingUtilities.invokeAndWait(() ->
        {
            ConfigFixture f = new ConfigFixture();
            f.nativeSelection(new LinkedHashSet<>(Arrays.asList(Patch.CORAL_E, Patch.CORAL_W)));
            f.set("autoOptimize", "false");
            ClassicTreeRunPanel panel = new ClassicTreeRunPanel(f.config, f);
            RunSettings settings = new RunSettings(f.config, f, panel);
            panel.setPrepareRun(settings::prepareNow);
            panel.onActivate();
            assertNotNull(find(panel, "CORAL_E"));
            assertNotNull(find(panel, "CORAL_W"));
            assertNull(find(panel, "FOSSIL_EAST"));
            settings.dispose();
        });
    }

    private static Component find(Container parent, String name)
    {
        for (Component child : parent.getComponents())
        {
            if (name.equals(child.getName())) { return child; }
            if (child instanceof Container)
            {
                Component found = find((Container) child, name);
                if (found != null) { return found; }
            }
        }
        return null;
    }

    private static void layout(Container parent)
    {
        parent.doLayout();
        for (Component child : parent.getComponents()) { if (child instanceof Container) { layout((Container) child); } }
    }
    private static void assertLabelsFit(Container parent)
    {
        for (Component child : parent.getComponents())
        {
            if (child instanceof JLabel && ((JLabel) child).getText().startsWith("<html>"))
            {
                assertTrue("Label clipped", child.getX() >= 0 && child.getX() + child.getWidth() <= parent.getWidth());
            }
            if (child instanceof Container) { assertLabelsFit((Container) child); }
        }
    }
    private static void capture(ClassicTreeRunPanel panel)
    {
        panel.setSize(225, 2000);
        layout(panel);
        assertLabelsFit(panel);
        BufferedImage image = new BufferedImage(225, 800, BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        try { panel.printAll(graphics); } finally { graphics.dispose(); }
        try
        {
            File file = new File("build/reports/sidebar-preview.png");
            file.getParentFile().mkdirs();
            ImageIO.write(image, "png", file);
        }
        catch (java.io.IOException error) { throw new RuntimeException(error); }
    }
}

package com.classictreerun;

import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class SupplyBankFilterTest
{
    private SupplyBankFilter filter()
    {
        SupplyBankFilter filter=new SupplyBankFilter();
        filter.start(SupplyPlan.build(new ClassicTreeRunConfig() { },List.of(Patch.LUMBRIDGE_TREE)));
        return filter;
    }
    @Test public void compactLayoutEnablesFilteringWithAnEmptyBankSearch()
    {
        SupplyBankFilter filter=filter();int[] stack={123,0};
        filter.filter("bankBuildTab",true,stack,2,-1,false);assertArrayEquals(new int[]{123,1},stack);
        int[] wanted={-1,ItemID.PLANTPOT_OAK_SAPLING};
        filter.filter("bankSearchFilter",true,wanted,2,ItemID.PLANTPOT_OAK_SAPLING,false);
        // RuneLite's -1 means defer to vanilla filtering, which accepts an empty search.
        assertArrayEquals(new int[]{-1,ItemID.PLANTPOT_OAK_SAPLING},wanted);
    }
    @Test public void unrelatedItemsAndPlaceholdersAreHiddenAndOtherFiltersArePreserved()
    {
        SupplyBankFilter filter=filter();
        int[] unrelated={-1,ItemID.RANARR_SEED};filter.filter("bankSearchFilter",true,unrelated,2,ItemID.RANARR_SEED,false);assertEquals(0,unrelated[0]);
        int[] placeholder={-1,ItemID.PLANTPOT_OAK_SAPLING};filter.filter("bankSearchFilter",true,placeholder,2,ItemID.PLANTPOT_OAK_SAPLING,true);assertEquals(0,placeholder[0]);
        int[] rejectedByOtherFilter={0,ItemID.PLANTPOT_OAK_SAPLING};filter.filter("bankSearchFilter",true,rejectedByOtherFilter,2,ItemID.PLANTPOT_OAK_SAPLING,false);assertEquals(0,rejectedByOtherFilter[0]);
    }
    @Test public void neverFiltersSharedStorageOrUnrelatedCallbacks()
    {
        SupplyBankFilter filter=filter();int[] stack={-1,ItemID.RANARR_SEED};
        filter.filter("bankSearchFilter",false,stack,2,ItemID.RANARR_SEED,false);assertEquals(-1,stack[0]);
        filter.filter("otherCallback",true,stack,2,ItemID.RANARR_SEED,false);assertEquals(-1,stack[0]);
        filter.filter("bankSearchFilter",true,stack,0,ItemID.RANARR_SEED,false);assertEquals(-1,stack[0]);
    }
    @Test public void waitsForBankAndClearsWhenItClosesOrWhenExplicitlyCleared()
    {
        SupplyBankFilter filter=filter();filter.bankVisible(false);assertTrue(filter.active());
        filter.bankVisible(true);filter.bankVisible(false);assertFalse(filter.active());
        filter=filter();filter.clear();int[] stack={-1,ItemID.RANARR_SEED};
        filter.filter("bankSearchFilter",true,stack,2,ItemID.RANARR_SEED,false);assertEquals(-1,stack[0]);
        filter.start(SupplyPlan.build(new ClassicTreeRunConfig() { },List.of()));assertFalse(filter.active());
    }
}

