package com.classictreerun;

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;
import static org.junit.Assert.*;

public class TreeSuppliesTest
{
    /** Concrete item forms from RuneLite 1.13.2 gameval ItemID, independent of the crop configuration. */
    @Test public void everyTreeUsesItsPlantableSaplingAndRejectsSeedsAndBothSeedlingForms() throws Exception
    {
        List<String> cases;
        try(BufferedReader reader=new BufferedReader(new InputStreamReader(
            getClass().getResourceAsStream("/tree-planting-items.csv"),StandardCharsets.UTF_8)))
        { cases=reader.lines().skip(1).collect(Collectors.toList()); }

        Set<CropChoices.Crop> covered=new HashSet<>();
        Set<Integer> saplings=cases.stream().map(line->Integer.parseInt(line.split(",")[3])).collect(Collectors.toSet());
        for(String line:cases)
        {
            String[] values=line.split(",");
            String name=values[0]+" / "+values[2];
            Patch.Type type=Patch.Type.valueOf(values[0]);
            int sapling=Integer.parseInt(values[3]),seed=Integer.parseInt(values[4]);
            int seedling=Integer.parseInt(values[5]),watered=Integer.parseInt(values[6]);
            ConfigFixture fixture=new ConfigFixture();fixture.set(values[1],values[2]);
            covered.add(CropChoices.forType(type,fixture.config));
            Patch patch=Arrays.stream(Patch.values()).filter(p->p.getType()==type).findFirst().orElseThrow();
            SupplyPlan plan=SupplyPlan.build(fixture.config,List.of(patch));
            SupplyPlan.Requirement requirement=plan.requirements.stream()
                .filter(row->row.item==sapling && !row.notes).findFirst().orElseThrow();
            assertEquals(name,1,requirement.quantity);

            SupplyBankFilter filter=new SupplyBankFilter();filter.start(plan);
            for(int id:new int[]{sapling,seed,seedling,watered})
            {
                int[] stack={-1,id};
                filter.filter("bankSearchFilter",true,stack,2,id,false);
                assertEquals(name+" item "+id,id==sapling ? -1 : 0,stack[0]);
                assertEquals("Item identity must be preserved",id,stack[1]);
            }
            for(int other:saplings)if(other!=sapling)assertFalse(name+" must not substitute sapling "+other,plan.items.contains(other));

            int index=plan.requirements.indexOf(requirement);
            SupplySnapshot unplantable=new SupplySnapshot(true,Map.of(seed,10L,seedling,10L,watered,10L),Map.of(sapling,10L));
            assertEquals(name+" seeds, seedlings and notes cannot satisfy the packing row",Long.valueOf(0),plan.carried(unplantable).get(index));
            SupplySnapshot plantable=new SupplySnapshot(true,Map.of(sapling,1L),Map.of());
            assertEquals(name,Long.valueOf(1),plan.carried(plantable).get(index));
        }

        Set<CropChoices.Crop> expected=new HashSet<>();
        for(CropChoices.Choice[] family:List.<CropChoices.Choice[]>of(CropChoices.Tree.values(),CropChoices.Fruit.values(),
            CropChoices.Hardwood.values(),CropChoices.Calquat.values(),CropChoices.Crystal.values(),
            CropChoices.Celastrus.values(),CropChoices.Redwood.values(),CropChoices.Spirit.values()))
            for(CropChoices.Choice choice:family)if(choice.crop().item!=-1)expected.add(choice.crop());
        assertEquals("Every available tree variant must be covered by this item-form fixture",expected,covered);
        assertEquals(23,covered.size());
    }
}

package net.runelite.pluginhub.packager;

import java.nio.file.*;
import java.io.*;
import net.runelite.pluginhub.apirecorder.API;

/** Local fixture only: no repository download, upload, credentials or game client. */
public class LocalHubCheck
{
    public static void main(String[] args) throws Exception
    {
        Path source=Path.of(args[0]).toAbsolutePath(),reports=Path.of(args[1]).toAbsolutePath();
        Files.createDirectories(reports);
        try(Plugin plugin=new Plugin(new File(args[2])))
        {
            try
            {
                Files.createDirectories(plugin.repositoryDirectory.toPath());
                for(String name:new String[]{"src","docs","tools",".github","gradle","README.md","LICENSE",
                    "THIRD-PARTY-NOTICES.md","build.gradle","settings.gradle","runelite-plugin.properties",".gitignore","gradlew","gradlew.bat"})
                {
                    Path from=source.resolve(name);if(!Files.exists(from))continue;
                    if(Files.isDirectory(from))
                    {
                        try(var paths=Files.walk(from))
                        {
                            for(Path p:(Iterable<Path>)paths::iterator)
                            {
                                Path to=plugin.repositoryDirectory.toPath().resolve(source.relativize(p));
                                if(Files.isDirectory(p))Files.createDirectories(to);else Files.copy(p,to);
                            }
                        }
                    }
                    else Files.copy(from,plugin.repositoryDirectory.toPath().resolve(name));
                }
                plugin.build("1.13.2",true);
                java.util.Properties metadata=new java.util.Properties();
                try(InputStream stream=Files.newInputStream(source.resolve("runelite-plugin.properties"))){metadata.load(stream);}
                String version=metadata.getProperty("version");
                if(!version.equals(plugin.getDisplayData().getVersion()))throw new IllegalStateException("Plugin Hub manifest version does not match source metadata");
                Files.writeString(reports.resolve("version.txt"),version+"\n");
                try(InputStream stream=Files.newInputStream(plugin.getApiFile().toPath()))
                {
                    String missing=API.decode(stream).missingFrom(Plugin.CURRENT_API).sorted().collect(java.util.stream.Collectors.joining("\n"));
                    if(!missing.isEmpty())throw new IllegalStateException("APIs missing from RuneLite 1.13.2:\n"+missing);
                }
                Path built=plugin.getLogFile().toPath().getParent();
                for(String name:new String[]{"plugin.jar","api","source.zip"})Files.copy(built.resolve(name),reports.resolve(name),StandardCopyOption.REPLACE_EXISTING);
                System.out.println("OFFICIAL LOCAL PACKAGER CHECK PASSED; API compatibility matched RuneLite 1.13.2.");
                System.out.println("Repository URL is a local test fixture. No GitHub publication, submission or remote-source validation was performed.");
            }
            finally
            {
                Files.copy(plugin.getLogFile().toPath(),reports.resolve("packager.log"),StandardCopyOption.REPLACE_EXISTING);
            }
        }
    }
}

package com.classictreerun;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public class ExportFarmingReference {
 public static void main(String[] args) throws Exception {
  Class<?> type=Class.forName("net.runelite.client.plugins.timetracking.farming.PatchImplementation");
  Method decode=type.getDeclaredMethod("forVarbitValue",int.class); decode.setAccessible(true);
  Class<?> state=Class.forName("net.runelite.client.plugins.timetracking.farming.PatchState");
  String[] methods={"getProduce","getCropState","getStage","getStages","getTickRate"};
  Method[] getters=new Method[methods.length]; for(int i=0;i<methods.length;i++){getters[i]=state.getDeclaredMethod(methods[i]);getters[i].setAccessible(true);}
  List<String> lines=new ArrayList<>(); lines.add("# RuneLite 1.13.2 crop state reference. See THIRD-PARTY-NOTICES.md.");
  for(Object implementation:type.getEnumConstants()) {
   String name=((Enum<?>)implementation).name(); if(name.contains("COMPOST"))continue;
   int last=-1;String lastValue=null;
   for(int raw=0;raw<65536;raw++) {
    Object current=decode.invoke(implementation,raw); String value=null;
    if(current!=null){List<String> fields=new ArrayList<>(); for(Method get:getters){Object v=get.invoke(current); fields.add(v instanceof Enum?((Enum<?>)v).name():String.valueOf(v));} value=String.join(",",fields);}
    if(!Objects.equals(lastValue,value)){if(lastValue!=null)lines.add(name+","+last+","+(raw-1)+","+lastValue);last=raw;lastValue=value;}
   }
   if(lastValue!=null)lines.add(name+","+last+",65535,"+lastValue);
  }
  Path file=Paths.get("build/reference/crop-states.csv");Files.createDirectories(file.getParent());Files.write(file,lines,StandardCharsets.UTF_8);
  Class<?> worldType=Class.forName("net.runelite.client.plugins.timetracking.farming.FarmingWorld");
  Constructor<?> constructor=worldType.getDeclaredConstructor();constructor.setAccessible(true);Object world=constructor.newInstance();
  Field regionField=worldType.getDeclaredField("regions");regionField.setAccessible(true);
  com.google.common.collect.Multimap<?,?> regions=(com.google.common.collect.Multimap<?,?>)regionField.get(world);
  Class<?> regionType=Class.forName("net.runelite.client.plugins.timetracking.farming.FarmingRegion");
  Method getId=regionType.getMethod("getRegionID"),getName=regionType.getMethod("getName"),getPatches=regionType.getMethod("getPatches");
  Class<?> patchType=Class.forName("net.runelite.client.plugins.timetracking.farming.FarmingPatch");
  Method patchName=patchType.getDeclaredMethod("getName"),varbit=patchType.getDeclaredMethod("getVarbit"),impl=patchType.getDeclaredMethod("getImplementation");
  for(Method m:new Method[]{patchName,varbit,impl})m.setAccessible(true);
  SortedSet<String> regionLines=new TreeSet<>();
  for(Map.Entry<?,?> entry:regions.entries()){
   Object region=entry.getValue();
   for(Object patch:(Object[])getPatches.invoke(region)){
    Object kind=impl.invoke(patch);String kindName=((Enum<?>)kind).name();if(kindName.contains("COMPOST"))continue;
    regionLines.add(entry.getKey()+","+getId.invoke(region)+","+getName.invoke(region)+","+patchName.invoke(patch)+","+varbit.invoke(patch)+","+kindName);
   }
  }
  Files.write(Paths.get("build/reference/regions.csv"),regionLines,StandardCharsets.UTF_8);
  Method getRegions=worldType.getDeclaredMethod("getRegionsForLocation",net.runelite.api.coords.WorldPoint.class);getRegions.setAccessible(true);
  List<String> mapped=new ArrayList<>();mapped.add("# patch,source-region,varbit,implementation,valid-regions");
  for(Patch ours:Patch.values()) {
   PatchSite site=ours.getSite();int x=site.x,y=site.y;
   if(ours==Patch.GUILD_HESPORI){x=1248;y=10060;}
   String kind=ours.getType().name();
   if(kind.equals("FRUIT"))kind="FRUIT_TREE";else if(kind.equals("HARDWOOD"))kind="HARDWOOD_TREE";else if(kind.equals("GRAPE"))kind="GRAPES";else if(kind.equals("CRYSTAL"))kind="CRYSTAL_TREE";else if(kind.equals("SPIRIT"))kind="SPIRIT_TREE";
   Collection<?> matching=(Collection<?>)getRegions.invoke(world,new net.runelite.api.coords.WorldPoint(x,y,0));
   List<Object[]> candidates=new ArrayList<>();
   for(Object region:matching)for(Object patch:(Object[])getPatches.invoke(region))if(((Enum<?>)impl.invoke(patch)).name().equals(kind))candidates.add(new Object[]{region,patch});
   String target="";String id=ours.name();
   for(String suffix:new String[]{"NW","NE","SW","SE","N","S","EAST","MIDDLE","WEST"})if(id.endsWith("_"+suffix)){target=suffix.replace("NW","North West").replace("NE","North East").replace("SW","South West").replace("SE","South East");if(suffix.equals("N"))target="North";if(suffix.equals("S"))target="South";if(suffix.equals("EAST"))target="East";if(suffix.equals("WEST"))target="West";if(suffix.equals("MIDDLE"))target="Middle";}
   if(id.startsWith("VINERY_"))target=(id.contains("_E")?"East ":"West ")+id.substring(id.length()-1);
   if(id.equals("CORAL_E"))target="East";if(id.equals("CORAL_W"))target="West";
   if(candidates.size()>1){final String desired=target;candidates.removeIf(pair->{try{return !patchName.invoke(pair[1]).equals(desired);}catch(Exception error){throw new RuntimeException(error);}});}
   if(candidates.size()!=1){throw new IllegalStateException("MISSING "+ours+" region="+new net.runelite.api.coords.WorldPoint(x,y,0).getRegionID()+" candidates="+candidates.size()+" target="+target);}
   Object region=candidates.get(0)[0],patch=candidates.get(0)[1];SortedSet<Integer> ids=new TreeSet<>();
   for(Map.Entry<?,?> entry:regions.entries())if(entry.getValue()==region)ids.add((Integer)entry.getKey());
   List<String> idText=new ArrayList<>();ids.forEach(v->idText.add(v.toString()));
   mapped.add(ours.name()+","+getId.invoke(region)+","+varbit.invoke(patch)+","+kind+","+String.join(";",idText));
  }
  Files.write(Paths.get("build/reference/patch-bindings.csv"),mapped,StandardCharsets.UTF_8);
  System.out.println("Exported "+(lines.size()-1)+" state ranges");
 }
}

package com.classictreerun;

import com.google.common.collect.Multimap;
import java.lang.reflect.*;
import java.util.*;
import net.runelite.api.coords.WorldPoint;

/** Offline compatibility audit only. Never packaged in the production plugin. */
public final class VerifyFarmingReference
{
    public static void main(String[] args) throws Exception
    {
        CropReference ours=new CropReference();
        String prefix="net.runelite.client.plugins.timetracking.farming.";
        Class<?> implementationType=Class.forName(prefix+"PatchImplementation");
        Method decode=accessible(implementationType,"forVarbitValue",int.class);
        Class<?> stateType=Class.forName(prefix+"PatchState");
        Method[] getters={accessible(stateType,"getProduce"),accessible(stateType,"getCropState"),
            accessible(stateType,"getStage"),accessible(stateType,"getStages"),accessible(stateType,"getTickRate")};
        Map<String,Patch> representatives=new TreeMap<>();
        for(CropReference.Binding binding:ours.bindings.values())representatives.putIfAbsent(binding.implementation,binding.patch);
        long states=0;
        for(Object implementation:implementationType.getEnumConstants())
        {
            String kind=((Enum<?>)implementation).name();Patch patch=representatives.get(kind);
            if(patch==null)continue;
            for(int raw=0;raw<=65535;raw++)
            {
                Object expected=decode.invoke(implementation,raw);CropReference.Crop actual=ours.decode(patch,raw);
                if(expected==null){require(actual==null,kind+" unexpected decoded value "+raw);}
                else
                {
                    require(actual!=null,kind+" missing raw value "+raw);
                    require(getters[0].invoke(expected).toString().equals(actual.produce)
                        && getters[1].invoke(expected).toString().equals(actual.state)
                        && (Integer)getters[2].invoke(expected)==actual.stage
                        && (Integer)getters[3].invoke(expected)==actual.stages
                        && (Integer)getters[4].invoke(expected)==actual.tickMinutes,kind+" differs at "+raw);
                }
                states++;
            }
        }
        Class<?> worldType=Class.forName(prefix+"FarmingWorld");
        Constructor<?> constructor=worldType.getDeclaredConstructor();constructor.setAccessible(true);
        Object world=constructor.newInstance();Field field=worldType.getDeclaredField("regions");field.setAccessible(true);
        Multimap<?,?> regions=(Multimap<?,?>)field.get(world);
        Class<?> regionType=Class.forName(prefix+"FarmingRegion"),patchType=Class.forName(prefix+"FarmingPatch");
        Method getId=regionType.getMethod("getRegionID"),getPatches=regionType.getMethod("getPatches"),bounds=regionType.getMethod("isInBounds",WorldPoint.class);
        Method getVarbit=accessible(patchType,"getVarbit"),getImplementation=accessible(patchType,"getImplementation");
        Map<String,Object> source=new HashMap<>();
        for(Object region:regions.values())
        {
            for(Object patch:(Object[])getPatches.invoke(region))
            {
                String kind=((Enum<?>)getImplementation.invoke(patch)).name();
                if(kind.contains("COMPOST"))continue;
                require(representatives.containsKey(kind),"New untracked crop family: "+kind);
                source.put(getId.invoke(region)+":"+getVarbit.invoke(patch)+":"+kind,region);
            }
        }
        Set<String> mapped=new HashSet<>();long points=0;
        for(CropReference.Binding binding:ours.bindings.values())
        {
            String key=binding.sourceRegion+":"+binding.varbit+":"+binding.implementation;
            Object region=source.get(key);require(region!=null,"Invalid binding: "+binding.patch);
            require(mapped.add(key),"Duplicate patch binding: "+binding.patch);
            Set<Integer> aliases=new HashSet<>();
            for(Map.Entry<?,?> entry:regions.entries())if(entry.getValue()==region)aliases.add((Integer)entry.getKey());
            require(aliases.equals(binding.regions),"Region aliases changed: "+binding.patch);
            for(int id:aliases)
            {
                int originX=(id>>8)*64,originY=(id&255)*64;
                for(int plane=0;plane<4;plane++)for(int x=originX;x<originX+64;x++)for(int y=originY;y<originY+64;y++)
                {
                    boolean expected=(Boolean)bounds.invoke(region,new WorldPoint(x,y,plane));
                    require(expected==binding.applies(x,y,plane),"Bounds differ: "+binding.patch+" at "+x+","+y+","+plane);
                    points++;
                }
            }
        }
        require(mapped.equals(source.keySet()),"Catalogue differs: RuneLite="+source.size()+", plugin="+mapped.size());
        System.out.println("Verified "+states+" raw decoder values across "+representatives.size()+" families, "+mapped.size()+" unique patch bindings, and "+points+" tile/plane boundary checks.");
    }
    private static Method accessible(Class<?> type,String name,Class<?>... parameters) throws Exception
    {Method method=type.getDeclaredMethod(name,parameters);method.setAccessible(true);return method;}
    private static void require(boolean passed,String message)
    {if(!passed)throw new IllegalStateException(message);}
}
